    "国标麻将指国家体育总局在1998出台的《中国竞技麻将比赛规则(试行)》中确立的麻将规则": "El mahjong MCR se basa en las reglas establecidas en el «Reglamento de competición del mahjong chino (provisional)», publicado por la Administración General del Deporte de China en 1998.",
