    "立直麻将一般指日本麻将，是麻将规则的一个分支。": "El mahjong Riichi suele referirse al mahjong japonés, una rama de las reglas de mahjong.",
    "GGHK 立直麻将规则书": "Reglamento de mahjong Riichi de GGHK",
    "香港麻将协会发布的立直麻将规则书": "Reglamento de Riichi publicado por la Asociación de Mahjong de Hong Kong",
    "青雀是由莫莫柴编写的一款麻雀规则，旨在寻求一种在传统麻将行牌规则框架内的做大、抢和、兜牌防守三者平衡的麻雀游戏，同时试图为各类和牌提供基于美感和难度评估的赋分参照。": "Qingque es un reglamento de mahjong creado por Momochai. Dentro de la estructura tradicional del juego, busca equilibrar la construcción de grandes manos, las victorias rápidas y la defensa, y ofrecer una referencia de puntuación para las manos ganadoras según su estética y dificultad.",
    "青雀一页纸": "Qingque en una página",
