    "本平台长沙麻将的规则说明（0709 更新）。": "Reglas de Changsha utilizadas en esta plataforma (actualización 0709).",
    "采用 144 张牌与 16 张手牌，并以台数结算的台湾麻将规则。": "Reglas de mahjong taiwanés con 144 fichas, manos de 16 fichas y puntuación en tai.",
    "台湾麻将台数表": "Tabla de tai de mahjong taiwanés",
    "本平台台湾麻将采用的台数参考表。": "Tabla de referencia de tai utilizada por el mahjong taiwanés de esta plataforma.",
    "十样锦麻将": "Mahjong Shiyangjin",
    "尚未实装该规则，此处仅提供规则书查阅。": "Estas reglas aún no están implementadas. Solo se ofrece el reglamento para consulta.",
    "十样锦麻将规则书": "Reglamento de mahjong Shiyangjin",
    "十样锦麻将规则说明。": "Explicación de las reglas de mahjong Shiyangjin.",
    "本规则为根据《绘图麻雀牌谱》《想定宁波规则》等书籍文献资料汇总而成的，试图还原1920年代左右或以前的早期麻将样貌的麻将规则。相比现代规则，古典麻雀有番种体系简单、重刻杠幺九、未和牌家计分等特点，具有独特风味。": "Estas reglas recopilan información de obras como «Huitu Maque Paipu» y «Xiangding Ningbo Guize» para recrear el mahjong de alrededor de la década de 1920 o anterior. Frente a las reglas modernas, el mahjong clásico tiene un sistema de jugadas sencillo, da más peso a pung, kong, terminales y honores, y puntúa también las manos de quienes no ganan, lo que le confiere un carácter propio.",
    "平台现行的古典麻将版本。": "Versión de mahjong clásico utilizada actualmente en la plataforma.",
    "■ 比赛列表": "■ Lista de torneos",
    "比赛 - salasasa.cn": "Torneos - salasasa.cn",
    "13 张直接显示听牌与进张，14 张显示切牌分析（副露按等价张数计算）。输入为空时将随机生成示例。": "Con 13 fichas se muestran las esperas y las mejoras; con 14, el análisis de descartes (las combinaciones expuestas cuentan por su número equivalente de fichas). Si la entrada está vacía, se generará un ejemplo aleatorio.",
