    "国标计算器 - salasasa.cn": "Calculadora MCR - salasasa.cn",
    "对局开始前服务器公布承诺值 = SHA256(主种子 + 盐值)，对局结束后公布主种子与盐值。 在此本地复现随机座位与每局配牌，验证服务器未中途更换种子。计算均在浏览器内完成。": "Antes de empezar, el servidor publica el compromiso = SHA256(semilla principal + sal). Al terminar, publica la semilla principal y la sal. Reproduce aquí los asientos y los repartos para comprobar que el servidor no cambió la semilla durante la partida. Todos los cálculos se realizan en el navegador.",
