    "对局局数": "Número de manos jugadas",
    "本场实际打的局数；立直 / 古典的连庄也算一局（局种子序号递增）": "Número real de manos jugadas; las repeticiones del repartidor en Riichi y Clásico también cuentan como manos (el índice de semilla aumenta).",
    "牌谱 player_entry_order 的顺序，留空则用 玩家1-4": "Orden de player_entry_order en el registro; si se deja vacío, se usará Jugador 1–4",
