    "牌谱格式转换": "Conversión de formatos de registros",
    "浏览器本地转换，支持国标：雀渣 ↔ salasasa ↔ Botzone；日麻：salasasa ↔ MJAI。 反向重建（尤其 Botzone→salasasa、salasasa→雀渣）在隐藏信息处为近似，请核对后再用于训练。": "Conversión local en el navegador. Admite MCR: Quezha ↔ salasasa ↔ Botzone; Riichi: salasasa ↔ MJAI. La reconstrucción inversa (especialmente Botzone→salasasa y salasasa→Quezha) aproxima la información oculta. Revísala antes de usarla para entrenar.",
    "转换方向": "Dirección de conversión",
    "雀渣 → salasasa（国标）": "Quezha → salasasa (MCR)",
    "salasasa → 雀渣（国标）": "salasasa → Quezha (MCR)",
