    "salasasa → MJAI（日麻）": "salasasa → MJAI (Riichi)",
    "MJAI → salasasa（日麻）": "MJAI → salasasa (Riichi)",
    "粘贴雀渣 raw（含 script）/ 解码 step / session+records JSON。": "Pega el JSON de Quezha: raw (con script), step decodificado o session+records.",
    "可靠程度：完整（推荐）": "Fiabilidad: completa (recomendado)",
    "字段 / 内容\t结果\t怎么处理\t例子": "Campo / contenido\tResultado\tTratamiento\tEjemplo",
    "手牌 / 牌山 / 摸切吃碰杠和\t完整\t按雀渣网页脚本位域原样解码，不猜测。": "Mano / muro / robos, descartes, chow, pung, kong y victoria\tCompleto\tDecodificación fiel de los campos de bits del script web de Quezha, sin conjeturas.",
    "摸 1 万 → [\"d\", 11]；手切 3 饼 → [\"c\", 23, \"F\"]": "Robar 1 de caracteres → [\"d\", 11]; descartar 3 de círculos de la mano → [\"c\", 23, \"F\"]",
    "番种 y → hu_fan\t完整\t用网页 FAN[] 表把番种编号还原成中文名。": "Jugada y → hu_fan\tCompleto\tLa tabla FAN[] de la web convierte el ID de la jugada a su nombre chino.",
    "索引 51 → \"混一色\"；花牌×2 → \"花牌*2\"": "Índice 51 → \"混一色\"; flores ×2 → \"花牌*2\"",
    "p0_uid … p3_uid\t近似\t雀渣玩家 id 是短字符串，salasasa 要整数，用字符串稳定哈希生成占位 uid。": "p0_uid … p3_uid\tAproximado\tLos ID de Quezha son cadenas cortas; salasasa exige enteros. Un hash estable de la cadena genera un uid provisional.",
    "雀渣 \"pm6Eet01\" → p0_uid: 955674184（不是真实 salasasa 账号）": "Quezha \"pm6Eet01\" → p0_uid: 955674184 (no es una cuenta real de salasasa)",
