    "赛事用于限时比赛；基地用于长期活动室。两者并列，审批通过后申请人成为主管理员。": "Los torneos son competiciones temporales; los clubes, espacios de actividad permanente. Son opciones independientes. Tras la aprobación, el solicitante será administrador principal.",
