    "发布比赛公告说明": "Guía para publicar anuncios",
    "您在包括且不限于以下情形时都可以发布比赛公告，并且您应该在1、4条所属情形发生时发布比赛公告，本平台对此不做严格规定。": "Puedes publicar anuncios en estos casos y en otros. Se recomienda hacerlo en los casos 1 y 4, aunque la plataforma no lo exige estrictamente.",
