    "赛事注册成功，在比赛开赛时可点击开始赛事按钮，开启赛事以后可开始创建比赛房间": "Torneo registrado. Cuando vaya a comenzar, pulsa «Iniciar torneo». Una vez abierto, podrás crear salas de torneo.",
