    "第三名扣除“段位均失 PT × 0.3 × 局制系数”，第四名扣除“段位均失 PT × 0.7 × 局制系数”。东风 0.49、半庄 0.7、全庄 1。": "Al tercer puesto se le resta «pérdida media de PT por rango × 0.3 × coeficiente de duración»; al cuarto, «pérdida media de PT por rango × 0.7 × coeficiente de duración». Coeficientes: Este 0.49, media partida 0.7, partida completa 1.",
