    "国标十六张：扩展规则与牌例": "MCR de dieciséis fichas: ampliación de reglas y ejemplos",
    "以新编 MCR 为底本的本站十六张扩展，含逐番适用表与五面子计分补则。": "Ampliación de dieciséis fichas de esta web, basada en Nueva edición MCR, con tabla de aplicación de cada jugada y reglas adicionales para puntuar cinco combinaciones.",
    "四人立直麻将，支持多种规则预设及役种、计分和流局设置": "Riichi para cuatro jugadores, con varios ajustes predefinidos y opciones de yaku, puntuación y manos nulas",
    "香港麻将协会发布的立直麻将规则书。": "Reglamento de Riichi publicado por la Asociación de Mahjong de Hong Kong.",
    "全国雀庄公式战手册 v1.0": "Manual de partidas oficiales de salones nacionales v1.0",
    "雀庄公式战预设所依据的公开手册。": "Manual público en el que se basa la configuración de partidas oficiales de salones.",
    "查看公开手册": "Ver manual público",
    "台湾麻将：使用144张牌与16张手牌，按台计分，支持公开报听、食替限制与八仙过海等规则。具体流程与台表可在馆规设置中选择。": "Mahjong taiwanés: 144 fichas, manos de 16 y puntuación en tai. Admite declaración pública de espera, restricciones de cambio inmediato de ficha y Ocho inmortales cruzan el mar, entre otras reglas. El procedimiento y la tabla de tai se eligen en las reglas de la casa.",
    "四川麻将（血战到底）": "Mahjong Sichuan (batalla hasta el final)",
    "长沙麻将经典双鸟规则：108张数牌，可吃上家牌，258将小胡，大胡可叠加，和牌后翻两只鸟并按座位中鸟加倍。": "Reglas clásicas de Changsha con dos pájaros: 108 fichas numerales, chow del jugador de la izquierda, victorias menores con pareja de 2, 5 u 8 y victorias mayores acumulables. Tras ganar se revelan dos pájaros; los aciertos por asiento duplican la puntuación.",
    "本平台长沙麻将规则说明。": "Reglas de mahjong Changsha de esta plataforma.",
    "也叫 MCR、中国麻将竞赛规则": "También llamado MCR o Reglas de Competición de Mahjong Chino",
