    "多版／平台伞称（1998原本另列）": "Nombre colectivo de varias versiones y plataformas (original de 1998 por separado)",
    "国标麻将规则资料，包含 Natsuki 编著的《新编 MCR》及各改编版本规则书。": "Documentación de MCR, incluida Nueva edición MCR, de Natsuki, y reglamentos de sus variantes.",
    "国标是多版规则及平台实现的伞称。1998原本题署7月、9月初版；WMO 2006和赛事补充须另看具名版本。平台使用的新编MCR不应与1998全文等同，原目录11月出台说已按原书更正。": "MCR engloba varias versiones y sus implementaciones. El original de 1998 está fechado en julio y su primera edición es de septiembre. WMO 2006 y los suplementos de torneos deben consultarse por su versión concreta. Nueva edición MCR, usada en la plataforma, no equivale al texto íntegro de 1998. La antigua referencia a noviembre se corrigió conforme al libro original.",
