    "请复制下方手牌链接": "Copia el enlace de la mano que aparece abajo",
    "副露用括号编码并区分大小写：": "Las combinaciones se codifican entre paréntesis, distinguiendo mayúsculas y minúsculas:",
    "为二三四万明顺，": "es un chow expuesto de 2, 3 y 4 de caracteres;",
    "为三饼暗刻；编码中的数字为项目牌号。": "es un pung oculto de 3 de círculos. Los números son los ID de fichas del proyecto.",
    "表示明顺 / 暗顺（数字取顺子中间牌）；": "representa chow expuesto / oculto (se usa el número de la ficha central);",
    "表示明刻 / 暗刻；": "representa pung expuesto / oculto;",
    "表示明杠 / 暗杠。": "representa kong expuesto / oculto.",
    "项目牌号：11–19 万、21–29 饼、31–39 条、41–44 东南西北、45 中、46 白、47 发；与": "ID del proyecto: 11–19 caracteres, 21–29 círculos, 31–39 bambúes, 41–44 Este-Sur-Oeste-Norte, 45 rojo, 46 blanco, 47 verde; el orden difiere de",
    "简写顺序不同。": "en la notación abreviada.",
    "例如": "Por ejemplo,",
    "后为单张和牌张。副露与简写双向同步，删除括号编码也会移除对应副露。": "va seguido de la ficha ganadora. Las combinaciones y la notación se sincronizan en ambos sentidos; borrar un código entre paréntesis también elimina su combinación.",
    "■ 麻雀计算器与猜番": "■ Calculadora de mahjong y reto de jugadas",
    "分析向听、进张与切牌，并计算和牌番种、得分及全部拆解。": "Analiza shanten, mejoras y descartes, y calcula jugadas, puntuación y todas las descomposiciones ganadoras.",
    "：万子，数字 1–9 表示一至九万；": ": caracteres; los números 1–9 representan del 1 al 9 de caracteres;",
    "表示赤五万（5m 的红宝牌写法）。": "representa el 5 rojo de caracteres (notación de dora roja para 5m).",
    "：饼（筒）子；": ": círculos;",
    "：条（索）子；写法同万子。": ": bambúes; se escribe igual que caracteres.",
    "：字牌，数字 1–7 依次为": ": honores; los números 1–7 corresponden, por orden, a",
    "同花色数字可连写，花色字母放在一段数字末尾，例如": "Los números del mismo palo pueden agruparse con su letra al final. Por ejemplo,",
    "表示万 123 与饼 456。": "representa 123 de caracteres y 456 de círculos.",
    "多段按顺序拼接即可，例如": "Basta con unir los grupos en orden. Por ejemplo,",
