    "我想添加自己的麻将规则\n(点击这里)": "Quiero añadir mis propias reglas\n(haz clic aquí)",
    "北京麻将（吃碰提）是北京地区的民间麻将规则，其特点为有字牌、无花牌、有万能牌、非门前清状态不可点和，番种体系较为简单。本文参考网络资料与线下实践梳理北京麻将的基本玩法，体现北京麻将核心特征，便于各地麻将爱好者了解北京麻将主要框架。": "El mahjong de Pekín (chi, peng y ti) es una modalidad popular local con honores, sin flores y con comodines. Solo permite ganar con descartes si la mano está oculta y tiene un sistema de jugadas sencillo. Este documento organiza sus reglas básicas a partir de fuentes en línea y práctica presencial, mostrando sus rasgos principales para que aficionados de otros lugares conozcan su estructura.",
