    "  项目简介": "  Acerca del proyecto",
    "open_mahjong_unity是一款基于unity/python-fastapi的麻将平台项目，该项目遵循MIT许可协议、免费、开源、支持PC/安卓/ios三端互通；目标是支持所有麻将规则、并且提供给玩家自定义规则的选项。欢迎加入q群906497522参与讨论、协助和测试。": "open_mahjong_unity es una plataforma de mahjong basada en unity/python-fastapi, gratuita y de código abierto bajo licencia MIT, con juego cruzado entre PC, Android e iOS. Su objetivo es admitir todas las reglas de mahjong y ofrecer opciones para personalizarlas. Únete al grupo de QQ 906497522 para debatir, colaborar y realizar pruebas.",
    "  随机种子": "  Semilla aleatoria",
    "在玩家 A 出牌时，若玩家 B、C 可对该出牌进行操作，则 B、C 会提前看到这张出牌；玩家 D 则会延迟一个「鸣牌保护时间」才看到出牌。若在鸣牌保护时间内 B、C 对出牌进行了操作，玩家 D 会立刻看见出牌，并在「第一追赶时间」之后再看见 B、C 其一执行的鸣牌申请或鸣牌。\n\n由于玩家 D 必定延迟一个第一追赶时间才看见 B、C 其一的鸣牌，若 B、C 在吃碰后快速出牌，这张出牌在 D 的视角中会显得「即时」。因此平台在触发鸣牌保护后进行出牌时，会保证至少再经过「第二追赶时间」才播放动画，避免在 D 的视角中出牌紧贴在吃碰之后生效。\n\n当前默认配置：\n鸣牌保护时间：1.3s\n第一追赶时间：0.7s\n第二追赶时间：0.5s": "Cuando el jugador A descarta, si B y C pueden actuar sobre esa ficha, la ven antes; D la ve tras un «tiempo de protección de reclamaciones». Si B o C actúan durante ese tiempo, D ve el descarte inmediatamente y, tras el «primer tiempo de sincronización», ve la solicitud de reclamación o la reclamación de B o C.\n\nComo D siempre ve esa reclamación con el retraso del primer tiempo de sincronización, si B o C descartan rápidamente después de reclamar un chow o pung, ese descarte parece «instantáneo» desde la perspectiva de D. Por ello, al descartar después de activar la protección de reclamaciones, la plataforma espera al menos un «segundo tiempo de sincronización» antes de reproducir la animación, para evitar que D vea el descarte justo después del chow o pung.\n\nValores predeterminados actuales:\nTiempo de protección de reclamaciones: 1.3s\nPrimer tiempo de sincronización: 0.7s\nSegundo tiempo de sincronización: 0.5s",
    "战术鸣牌的设计来源于雀渣：在其他家申请鸣牌以后，可用更高优先级的操作打断他家更低优先级的操作，以模拟线下刻意「碰断吃」等战术。\n\n示例一：玩家 A 出牌 T，玩家 B 可吃、玩家 C 可碰。此时 C 选择跳过，但 B 点击了吃牌；由于仍存在可执行的更高优先级操作，系统会再次询问 C 是否要碰，以模拟国标线下允许刻意用碰打断别人吃的情形。\n\n示例二：玩家 A 出牌 T，玩家 B 可吃或和牌，玩家 C 可碰。B 选择吃，C 用碰打断了 B 的吃；此时 B 不再能用和去打断 C 的碰。这符合国标不允许玩家在鸣牌发声后更改自己要执行动作的规则。": "El diseño de las reclamaciones tácticas procede de Quezha: después de que otro jugador solicite una reclamación, una acción de mayor prioridad puede interrumpir otra de menor prioridad, para reproducir tácticas presenciales como interrumpir deliberadamente un chow con un pung.\n\nEjemplo uno: A descarta T, B puede reclamar chow y C puede reclamar pung. C pasa, pero B pulsa chow; como aún hay una acción de mayor prioridad disponible, el sistema vuelve a preguntar a C si quiere reclamar pung, reproduciendo la posibilidad de interrumpir deliberadamente un chow con un pung en MCR presencial.\n\nEjemplo dos: A descarta T, B puede reclamar chow o ganar y C puede reclamar pung. B elige chow y C lo interrumpe con pung; B ya no puede interrumpir el pung de C declarando victoria. Esto respeta la regla de MCR que impide cambiar de acción después de anunciar una reclamación.",
    "  添加规则": "  Añadir reglas",
    "  相关链接": "  Enlaces relacionados",
