    "手牌牌面背景：用于在手牌牌面使用透明通道的情况下替换背景，默认尺寸 272*389。\n手牌牌背：用于在里宝牌区或者2D展示中显示牌背\n3D牌面背景：用于在3D卡牌的正面叠底在3D花纹下显示\n上传成对 zip格式：hand-back.png + hand-bg.png。": "Fondo de las fichas de la mano: sustituye el fondo cuando la cara tiene transparencia; tamaño predeterminado 272*389.\nReverso de las fichas de la mano: se muestra en la zona de ura dora o en las vistas 2D.\nFondo de las caras 3D: se muestra debajo del dibujo 3D en el anverso de las fichas 3D.\nFormato del zip con el par: hand-back.png + hand-bg.png.",
