    "段位 PT = q ×（k × M - C）；q 为局制系数，k 为场次倍率，C 见段位扣分表": "PT de rango = q × (k × M - C); q es el coeficiente de duración, k el multiplicador de la modalidad y C figura en la tabla de deducciones por rango",
    "倍率 k": "Multiplicador k",
