    "普通入场段位": "Rango de acceso habitual",
    "C 为负数时是保护奖励；PT 保留两位小数。十段固定 100/100 PT，每场变动为 0。": "Cuando C es negativo, concede una bonificación de protección; los PT se conservan con dos decimales. El 10.º dan tiene 100/100 PT fijos y una variación de 0 por partida.",
    "立直 · 段位升降与扣分表": "Riichi · Tabla de ascensos, descensos y deducciones",
    "各名次扣相同的 C；东风整体乘 0.7，负数为保护奖励。特许可突破最低段位；— 为禁入场次。": "Todas las posiciones descuentan el mismo C; en ronda Este se multiplica el total por 0.7. Los valores negativos son bonificaciones de protección. El acceso especial permite omitir el rango mínimo; — indica modalidades no permitidas.",
