    "背包  ·  0 件": "Inventario  ·  0 objetos",
    "暂无物品": "Sin objetos",
    "装扮": "Apariencia",
    "点击改名": "Pulsa para cambiar de nombre",
    "段位与匹配说明": "Rangos y emparejamiento",
    "为适配不同人数的游玩规则的匹配机制，平台目前提供以下两种段位设计\n1.对于每日对于超过100局的麻将规则，使用以级段制为主的段位系统\n2.对于每日对局低于100局的麻将规则，使用以elo为主的匹配系统进行对局，待人数提升后，按照elo排名设计级段制段位，并通过elo对玩家的段位进行赋分\n3.对于娱乐、开发中或不需添加段位机制的规则，不开设段位匹配场": "Para adaptar el emparejamiento a reglas con distintas cantidades de jugadores, la plataforma ofrece actualmente estos dos sistemas de rangos:\n1. Para reglas con más de 100 manos diarias, se usa un sistema basado en kyu y dan.\n2. Para reglas con menos de 100 manos diarias, se usa un emparejamiento basado en Elo. Cuando aumente el número de jugadores, se diseñarán rangos kyu y dan según la clasificación Elo y se asignarán puntos de rango mediante Elo.\n3. Las reglas recreativas, en desarrollo o que no necesiten rangos no tendrán salas de emparejamiento clasificatorio.",
    "Elo 匹配\n\n各规则独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副）。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32；川麻 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n青雀使用独立的局均素点算法，详见青雀页面。国标、立直仅结算段位/PT；自定义对局不计分。": "Emparejamiento Elo\n\nCada conjunto de reglas tiene su puntuación independiente. Hongque permite media partida de 8 manos o partida completa de 16; Sichuan batalla hasta el final y río de sangre con intercambio de tres fichas usan media partida (8 manos). Se empareja por orden de entrada y la partida comienza en cuanto hay cuatro jugadores.\nR inicial = 1500, denominador 2400. En Hongque, K=16 para media partida y K=32 para completa; en Sichuan, K=32. La posición final se compara con los tres rivales; las posiciones iguales cuentan como empate. Si la R media de la mesa es inferior a 1500, se añade protección, sin mínimo individual.\n\nQingque usa un algoritmo independiente de puntos brutos medios por mano; consulta su página. MCR y riichi solo liquidan rango/PT; las partidas personalizadas no puntúan.",
    "放弃比赛": "Abandonar partida",
    "检测到您有一场正在进行的游戏，是否返回游戏?": "Tienes una partida en curso. ¿Quieres volver a ella?",
    "刷新房间列表成功": "Lista de salas actualizada",
    "Elo 匹配\n\n青雀、虹雀、川麻血战、血流换三张独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副），青雀为全庄战。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32，两种局制共用虹雀积分；其他 Elo 规则 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n问号内显示算法。国标、立直仅结算段位/PT；自定义对局不计分。": "Emparejamiento Elo\n\nQingque, Hongque, Sichuan batalla hasta el final y río de sangre con intercambio de tres fichas tienen puntuaciones independientes. Hongque permite media partida de 8 manos o partida completa de 16; Sichuan batalla hasta el final y río de sangre con intercambio de tres fichas usan media partida (8 manos), y Qingque, partida completa. Se empareja por orden de entrada y la partida comienza en cuanto hay cuatro jugadores.\nR inicial = 1500, denominador 2400. En Hongque, K=16 para media partida y K=32 para completa; ambas duraciones comparten puntuación. Las demás reglas Elo usan K=32. La posición final se compara con los tres rivales; las posiciones iguales cuentan como empate. Si la R media de la mesa es inferior a 1500, se añade protección, sin mínimo individual.\n\nEl signo de interrogación muestra el algoritmo. MCR y riichi solo liquidan rango/PT; las partidas personalizadas no puntúan.",
