    "把牌先分成三类：数牌、字牌、花牌。\n不用急着记番种，今天先认清牌面。": "Primero divide las fichas en tres tipos: numerales, honores y flores.\nNo hace falta memorizar aún las jugadas; hoy aprenderemos a reconocer las fichas.",
