    "琪露诺": "Cirno",
    "欢迎来到麻雀教室！我是琪露诺。先一起认识麻将牌吧——数牌 108 张，字牌 28 张，再加 8 张花牌。": "¡Bienvenido a la clase de mahjong! Soy Cirno. Conozcamos las fichas: 108 numerales, 28 honores y 8 flores.",
