    "返回修改": "Volver a editar",
    "<b>青雀 · 局均素点 Elo</b>\n初始 R = 1500；全庄与无固定时限共用积分。\nN = 实际完成局数（包含流局），Y = 累计净素点。\n局均 A = Y / N；桌均 M = 四人 R 的平均值。\n预期局均 = (自己 R - M) / 32\n普通变化 = 32N / (N + 1584) × (A - 预期局均)\n不按名次计分，不设涨跌硬上限。\n保护系数 K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((对手 R - 自己 R) / 2400))\nE' = 1 / (1 + 10^((对手 R + T - 自己 R) / 2400))\n指数限制在 -16 至 16；合计为三个对手之和。\n保护奖励 = (K / 3) × 合计(E - E')\n新 R = 原 R + 普通变化 + 保护奖励。\n普通变化按分币分配余差保持零和，保护另取两位。\n同为1500分、16局：净赢800加16，1600加32。\n未完成局不计入；零完成局不结算。": "<b>Qingque · Elo de puntos brutos medios por mano</b>\nR inicial = 1500; partida completa y sin límite de tiempo fijo comparten puntuación.\nN = manos completadas (incluidas las nulas), Y = puntos brutos netos acumulados.\nMedia por mano A = Y / N; media de mesa M = media de las R de los cuatro jugadores.\nMedia prevista por mano = (R propia - M) / 32\nVariación normal = 32N / (N + 1584) × (A - media prevista por mano)\nNo puntúa por posición ni impone un límite absoluto de subida o bajada.\nCoeficiente de protección K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((R del rival - R propia) / 2400))\nE' = 1 / (1 + 10^((R del rival + T - R propia) / 2400))\nEl exponente se limita de -16 a 16; la suma abarca los tres rivales.\nBonificación de protección = (K / 3) × suma(E - E')\nNueva R = R anterior + variación normal + bonificación de protección.\nLa variación normal reparte el residuo en centésimas para mantener suma cero; la protección se redondea por separado a dos decimales.\nTodos con 1500 puntos, 16 manos: ganar 800 netos suma 16; 1600 suma 32.\nLas manos incompletas no cuentan; con cero manos completadas no se liquida.",
    "麻雀教室": "Clase de mahjong",
