    "调整所有声音的总体音量。": "Ajusta el volumen general de todos los sonidos.",
    "调整背景音乐的音量。": "Ajusta el volumen de la música de fondo.",
    "调整操作与对局音效的音量。": "Ajusta el volumen de los efectos de las acciones y la partida.",
    "调整角色语音的音量。": "Ajusta el volumen de las voces de los personajes.",
    "设置和牌时是否播放锣声音效。": "Elige si suena el gong al ganar una mano.",
    "设置匹配成功时是否播放提示音。": "Elige si suena un aviso al encontrar partida.",
    "选择摸切的鼠标快捷操作，或关闭快捷操作。": "Elige el atajo de ratón para descartar la ficha robada o desactívalo.",
    "选择取消响应的鼠标快捷操作，或关闭快捷操作。": "Elige el atajo de ratón para cancelar la respuesta o desactívalo.",
    "开启后先选中手牌，再次点击确认出牌。": "Al activarlo, selecciona primero una ficha y pulsa de nuevo para descartarla.",
    "设置进入对局时是否默认开启自动补花。": "Elige si la reposición automática de flores se activa al entrar en la partida.",
    "在规则允许时显示强制过操作。": "Muestra la acción de pasar forzosamente cuando las reglas lo permitan.",
    "隐藏聊天，并遮蔽房间信息与其他玩家昵称。": "Oculta el chat, la información de la sala y los nombres de otros jugadores.",
    "选择实时观战申请的处理方式：询问、自动同意或自动拒绝。": "Elige cómo responder a las solicitudes para observar en tiempo real: preguntar, aceptar o rechazar automáticamente.",
    "手牌示例随当前花色、字牌和三元牌顺序调整。": "El ejemplo de mano sigue el orden actual de palos, honores y dragones.",
    "非日麻规则下的三元牌排列示例。": "Ejemplo de orden de dragones fuera de riichi.",
    "日麻规则下的三元牌排列示例。": "Ejemplo de orden de dragones en riichi.",
    "调整万、索、饼的排列顺序，下方手牌同步预览。": "Ajusta el orden de caracteres, bambúes y círculos; la mano inferior se actualiza como vista previa.",
    "调整字牌与数牌的先后顺序，下方手牌同步预览。": "Ajusta el orden de honores y fichas numerales; la mano inferior se actualiza como vista previa.",
    "调整非日麻规则下中、发、白的排列顺序。": "Ajusta el orden de rojo, verde y blanco fuera de riichi.",
    "调整日麻规则下中、发、白的排列顺序。": "Ajusta el orden de rojo, verde y blanco en riichi.",
    "切换白板牌面的纯白或回形样式。": "Alterna entre dragón blanco liso y con marco.",
    "设置对局操作按钮是否使用分类颜色。": "Elige si los botones de acción usan colores por categoría.",
    "3D 牌描边使用标准样式。": "Usa el contorno estándar para las fichas 3D.",
    "设置副露牌组之间是否留出间距；规则要求时固定开启。": "Elige si se deja espacio entre las combinaciones expuestas; se activa obligatoriamente cuando las reglas lo exigen.",
    "切换游戏界面的显示语言。": "Cambia el idioma de la interfaz del juego.",
    "设置画面帧率上限；开启垂直同步时由同步设置决定。": "Establece el límite de fotogramas; con sincronización vertical activa, lo determina esta.",
    "让画面刷新与显示器同步，减少画面撕裂。": "Sincroniza la imagen con la pantalla para reducir los cortes de imagen.",
    "当前规则固定开启副露间距。": "Estas reglas exigen espacio entre las combinaciones expuestas.",
    "原版修整": "Original retocado",
