    "关联类": "Relaciones",
    "和牌由庄家的13张配牌与第一张摸牌组成。": "La mano ganadora consta de las 13 fichas repartidas al repartidor y su primer robo.",
    "和牌由闲家的13张配牌与庄家的首张舍牌组成。若庄家已有暗杠，则地和不成立。": "La mano ganadora consta de las 13 fichas repartidas a un jugador no repartidor y el primer descarte del repartidor. Si este ya declaró un kong oculto, no cuenta la victoria terrestre.",
    "和自家开杠后摸得的牌。": "Ganar con la ficha robada después de declarar un kong propio.",
    "摸牌墙中最后一张牌得和。": "Ganar robando la última ficha del muro.",
    "牌墙已被摸完时，他家放铳得和。": "Ganar con un descarte de otro jugador después de agotar el muro.",
    "和别家加杠之牌。": "Ganar con la ficha que otro jugador usa para ampliar un kong.",
    "由十三种幺九牌（一、九数牌及字牌）各一，加上任意一张幺九牌组成的特殊和牌。": "Forma especial con una ficha de cada uno de los trece terminales y honores (unos, nueves y honores) más cualquier terminal u honor adicional.",
    "由七个对子组成的特殊和牌。": "Forma especial compuesta de siete parejas.",
    "除和张外的所有牌张皆由自家摸得的和牌。": "Todas las fichas salvo la ganadora se han robado del muro.",
