    "番牌七对": "Siete parejas de honores de valor",
    "仅由番牌对子组成的七对和牌。": "Una mano de siete parejas formada solo por honores de valor.",
    "番牌六对": "Seis parejas de honores de valor",
    "包含番牌六对以上的七对和牌。": "Una mano de siete parejas que contiene al menos seis parejas de honores de valor.",
    "铳和；门风北": "Victoria por descarte; viento propio Norte",
    "番牌五对": "Cinco parejas de honores de valor",
    "包含番牌五对以上的七对和牌。": "Una mano de siete parejas que contiene al menos cinco parejas de honores de valor.",
    "番牌四副": "Cuatro grupos de honores de valor",
    "和牌中有番牌四副（对子或刻子）以上。": "La mano contiene al menos cuatro grupos de honores de valor (parejas o pungs).",
    "番牌三副": "Tres grupos de honores de valor",
    "和牌中有番牌三副（对子或刻子）以上。": "La mano contiene al menos tres grupos de honores de valor (parejas o pungs).",
    "自摸；门风南": "Victoria del muro; viento propio Sur",
    "番牌二副": "Dos grupos de honores de valor",
    "和牌中有番牌两副（对子或刻子）以上。": "La mano contiene al menos dos grupos de honores de valor (parejas o pungs).",
    "番牌": "Honores de valor",
    "和牌中有番牌一副（对子或刻子）以上。": "La mano contiene al menos un grupo de honores de valor (pareja o pung).",
    "和牌仅由一、九序数牌组成。": "La mano solo contiene fichas numerales de uno y nueve.",
    "和牌仅由一、九序数牌和/或字牌组成。": "La mano solo contiene fichas numerales de uno y nueve y/o honores.",
    "清带幺": "Terminales en todos los grupos",
    "每一组牌（对子、顺子或刻子）均包含一、九序数牌的和牌。": "Cada grupo (pareja, chow o pung) contiene una ficha numeral de uno o nueve.",
    "混带幺": "Terminales u honores en todos los grupos",
    "每一组牌（对子、顺子或刻子）均包含一、九序数牌或字牌的和牌。": "Cada grupo (pareja, chow o pung) contiene una ficha numeral de uno o nueve o un honor.",
    "立牌为同色的1112345678999（此时待牌为所有同色牌张），并和牌。": "Ganar con 1112345678999 de un mismo palo en la mano (esperando cualquier ficha de ese palo).",
    "和牌仅由一色的序数牌组成。": "La mano solo contiene fichas numerales de un palo.",
    "和牌仅由一色的序数牌和/或字牌组成。": "La mano solo contiene fichas numerales de un palo y/o honores.",
    "包含风牌、三元牌和全部三种花色的序数牌的一般形和牌。": "Una mano de forma básica que contiene vientos, dragones y fichas numerales de los tres palos.",
    "混一数": "Un número y honores",
    "和牌仅由一种序数的序数牌和/或字牌组成。": "La mano solo contiene fichas de un mismo número y/o honores.",
    "二数": "Dos números",
    "和牌仅由两种序数的序数牌组成。": "La mano solo contiene fichas de dos números distintos.",
    "二聚": "Dos números consecutivos",
    "和牌仅由连续的某两种序数的序数牌组成。": "La mano solo contiene fichas de dos números consecutivos.",
    "三聚": "Tres números consecutivos",
    "和牌仅由连续的某三种序数的序数牌组成，其中可以缺少部分序数。": "La mano solo contiene fichas dentro de tres números consecutivos; puede faltar alguno.",
    "四聚": "Cuatro números consecutivos",
    "和牌仅由连续的某四种序数的序数牌组成，其中可以缺少部分序数。": "La mano solo contiene fichas dentro de cuatro números consecutivos; puede faltar alguno.",
    "连数": "Números consecutivos sin solaparse",
    "和牌仅由序数牌组成，含且仅含连续的某几种序数，且任意两组牌（对子、顺子或刻子）之间都没有重复序数。": "La mano solo contiene fichas numerales de un intervalo consecutivo, sin otros números; ningún par de grupos (parejas, chows o pungs) comparte números.",
    "间数": "Números equidistantes",
    "和牌仅由不连续但间隔相同的序数的序数牌组成，其中可以缺少部分序数，但至少要有三种序数。": "La mano solo contiene fichas de números no consecutivos, pero equidistantes. Pueden faltar algunos números, aunque debe haber al menos tres distintos.",
    "镜数": "Simetría numérica",
    "仅由序数牌组成的和牌，其中每个花色中的牌张组合关于同一个序数对称。即，存在一整数q，使得将和牌的某个拆解方式中的每个部分的序数关于q镜像后，仍是原来的拆解方式。此处面子的明与暗，刻子是否成杠均不作区分。": "La mano solo contiene fichas numerales y los grupos de cada palo son simétricos respecto a un mismo número. Es decir, existe un entero q tal que reflejar respecto a q los números de cada parte de alguna descomposición de la mano produce la misma descomposición. No se distingue entre combinaciones ocultas o expuestas, ni entre pung y kong.",
    "映数": "Reflejo entre palos",
    "仅由序数牌组成的和牌，其中一种花色中的牌张组合关于一个序数对称，另两种花色互为关于同一序数的镜像。即，存在一整数q，使得将和牌的某个拆解方式中的每个部分的序数关于q镜像后，交换两种花色，仍是原来的拆解方式。此处面子的明与暗，刻子是否成杠均不作区分。": "La mano solo contiene fichas numerales: los grupos de un palo son simétricos respecto a un número y los otros dos palos son reflejos entre sí respecto a ese mismo número. Es decir, existe un entero q tal que reflejar respecto a q los números de cada parte de alguna descomposición y después intercambiar dos palos produce la misma descomposición. No se distingue entre combinaciones ocultas o expuestas, ni entre pung y kong.",
    "满庭芳": "Número común en todos los grupos",
    "和牌仅由序数牌组成，其中每个面子均包含雀头的序数。": "La mano solo contiene fichas numerales y cada combinación incluye el número de la pareja.",
    "四同顺": "Cuatro chows idénticos",
