    "三连环": "Tres chows entrelazados",
    "和牌中有同色至少三副序数依次递增2的顺子。": "La mano contiene al menos tres chows del mismo palo cuyos números aumentan de dos en dos.",
    "一气贯通": "Escalera pura",
