    "三色二对": "Dos tríos de parejas en tres palos",
    "七对和牌中，有独立的两组三色三副序数相同的对子。": "Una mano de siete parejas con dos grupos independientes de tres parejas del mismo número, una de cada palo.",
    "三色同对": "Parejas iguales en tres palos",
    "七对和牌中，有三色三副序数相同的对子。": "Una mano de siete parejas con tres parejas del mismo número, una de cada palo.",
    "三色连刻": "Pungs consecutivos en tres palos",
    "和牌中有三色三副序数依次递增1的刻子。": "La mano contiene tres pungs cuyos números aumentan de uno en uno, uno de cada palo.",
    "三色贯通": "Escalera en tres palos",
    "和牌中有三色三副序数依次递增3的顺子，即一色的123、另一色的456和余下一种花色的789。": "La mano contiene tres chows cuyos números aumentan de tres en tres, uno de cada palo: 123 de un palo, 456 de otro y 789 del restante.",
    "镜同": "Grupos iguales en dos palos",
    "和牌中有两色序数牌各组成两副面子，其中对于一种花色的任一面子，在另一种花色中均有与之序数相同的面子；此处刻子是否成杠均不作区分。": "La mano contiene dos combinaciones en cada uno de dos palos; cada combinación de un palo tiene otra de los mismos números en el otro. No se distingue entre pung y kong.",
    "镜同三对": "Tres parejas iguales en dos palos",
    "在七对和牌中，有三个同花色的序数牌对子，且另一序数牌花色中有三个序数与它们对应相同的对子。": "Una mano de siete parejas con tres parejas numerales de un palo y otras tres de los mismos números en otro palo.",
    "镜同二对": "Dos parejas iguales en dos palos",
    "在七对和牌中，有两个同花色的序数牌对子，且另一序数牌花色中有两个序数与它们对应相同的对子。": "Una mano de siete parejas con dos parejas numerales de un palo y otras dos de los mismos números en otro palo.",
    "双龙会": "Dos escaleras cortas",
    "和牌中有独立的两组各两副同色且序数相差3的顺子。": "La mano contiene dos grupos independientes de dos chows del mismo palo separados por tres números cada uno.",
