    "鹫巢麻将规则变体，四位玩家分为A、B两队，助手坐上家，主将坐下家，副将无击飞，最终两队只比对主将的分数判断胜负，鹫巢双打没有连庄。": "Variante de mahjong Washizu: los cuatro jugadores se dividen en equipos A y B. El asistente se sienta antes que el capitán en el orden de turno. El asistente no queda eliminado por puntos negativos. La victoria se decide comparando únicamente los puntos de los capitanes. En Washizu dobles, el repartidor no repite.",
