    "无癞子奖励：可选无癞子+8分（默认）、无癞子翻倍或不额外加分。先以不含花分和奖励的牌型番判定起和，再对牌型番加黑花分进行奖励；国标支付底分8不变。花杠不享受无癞子奖励。": "Bonificación sin comodines: +8 puntos (predeterminado), doblar o no añadir puntos. Primero se comprueba el mínimo para ganar con los puntos de la forma, sin flores ni bonificación. Después se aplica la bonificación a los puntos de la forma más los de flores negras. La base de pago MCR sigue siendo 8. Los grupos de flores no reciben esta bonificación.",
    "黑花递增计分：开启时梅兰竹菊1、2、3、4朵合计4、8、16、32番；关闭时每朵1番。花分不计入起和门槛。": "Puntuación creciente de flores negras: activada, 1, 2, 3 o 4 flores de ciruelo, orquídea, bambú y crisantemo suman 4, 8, 16 o 32 puntos; desactivada, cada flor vale 1 punto. Las flores no cuentan para el mínimo de victoria.",
