    " · 番种记录": " · Registro de jugadas",
    "日汇总截止 ": "Resumen diario hasta ",
    "平台累计\n按当前规则及场次读取公开牌谱统计，对局按 game_id 去重。全场次含匹配、自定义和赛事；四张场次卡始终展示当前规则的累计数量。\n\n匹配场行为数据\n累计手数为全桌手数；平均和牌 = 总和牌番值 ÷ 和牌次数；自摸占和牌 = 自摸次数 ÷ 和牌次数。不展示个人胜率和个人顺位。\n\n每日对局量\n时间窗口只作用于日汇总，不改变累计指标与最近牌谱。统计日以北京时间 04:00 切日，截止最近已完成聚合日。缺少记录的日期留空，不补零。\n\n场次与局制\n初级、中级、高级、自定义的累计计数来自网站首页的原始牌谱归口接口。自定义部分缺少完整行为指标，只展示已提供的对局计数。\n\n最近对局\n全场次时展示匹配场公共牌谱，可按等级场筛选、翻页并查看同桌结算。赛事单独查询；现有接口未提供自定义房间公共牌谱列表。\n\n番种记录\n累计出现次数可重复，不是互斥占比。所选场次无支持时显示不可用。": "Totales de la plataforma\nEstadísticas de registros públicos según las reglas y modalidad actuales, sin duplicados de game_id. Todas las modalidades incluye emparejamiento, personalizadas y torneos; las cuatro tarjetas siempre muestran los totales de las reglas actuales.\n\nAcciones en salas de emparejamiento\nLas manos acumuladas son las de toda la mesa; victoria media = valor total de las manos ganadoras ÷ número de victorias; proporción de victorias del muro = victorias del muro ÷ victorias. No se muestran tasas de victoria ni posiciones individuales.\n\nPartidas diarias\nEl intervalo temporal solo afecta al resumen diario, no a los totales ni a los registros recientes. El día estadístico cambia a las 04:00 de Pekín y llega hasta el último día agregado completo. Las fechas sin registros quedan vacías, sin rellenarlas con cero.\n\nModalidades y duración\nLos totales de inicial, intermedia, avanzada y personalizada proceden de la interfaz original de registros de la página de inicio. Las personalizadas no tienen métricas completas de acciones; solo muestran los recuentos disponibles.\n\nPartidas recientes\nEn todas las modalidades se muestran registros públicos de emparejamiento. Se pueden filtrar por nivel de sala, paginar y consultar resultados de la mesa. Los torneos se consultan por separado; la interfaz actual no ofrece listas de registros públicos de salas personalizadas.\n\nRegistro de jugadas\nLos recuentos acumulados pueden solaparse; no son porcentajes excluyentes. Si la modalidad elegida no los admite, se muestra que no están disponibles.",
    "符": "Fu",
    "台": "Tai",
    "点": "Puntos",
    " 局": " manos",
    "已解析 ": "Analizadas ",
    " 场": " partidas",
    "本规则暂未提供逐局统计": "Estas reglas aún no ofrecen estadísticas por mano",
    "统计范围\n所选规则、房间类型与日期同时作用于战绩和对局列表。\n\n和牌率 / 放铳率\n个人和牌次数 / 放铳次数 ÷ 参与的手数。\n\n自摸占和牌\n自摸次数 ÷ 和牌次数；不是每手自摸率。\n\n副露率\n个人副露手数 ÷ 参与的手数。\n\n平均顺位\n各顺位场次 × 顺位之和 ÷ 总场次。\n\n番种记录\n记录累计出现次数，可重复计数，不是互斥占比。\n\n近期走势\n最近最多 20 场，按时间从旧到新。缺少明细的指标显示“—”。": "Ámbito de las estadísticas\nLas reglas, tipo de sala y fechas elegidos se aplican tanto al historial como a la lista de partidas.\n\nTasa de victoria / tasa de descarte ganador dado\nVictorias personales / descartes ganadores dados ÷ manos jugadas.\n\nProporción de victorias del muro\nVictorias del muro ÷ victorias; no es la tasa de victoria del muro por mano.\n\nTasa de mano expuesta\nManos personales con reclamaciones ÷ manos jugadas.\n\nPosición media\nSuma de partidas en cada posición × esa posición ÷ total de partidas.\n\nRegistro de jugadas\nCuenta las apariciones acumuladas, que pueden solaparse; no son porcentajes excluyentes.\n\nEvolución reciente\nHasta las últimas 20 partidas, de más antigua a más reciente. Las métricas sin detalle se muestran como «—».",
