    "牌例：": "Ejemplo:",
    "东、南、西、北分别组成四组刻子或杠子，另有一对将。": "Cuatro pungs o kongs de Este, Sur, Oeste y Norte, más una pareja.",
    "中、发、白三组箭牌刻子或杠子，另有一组面子和将。": "Tres pungs o kongs de dragones rojo, verde y blanco, más otra combinación y la pareja.",
    "仅使用 23468 条与发牌，例如 234678 条刻顺组合。": "Solo se usan 23468 de bambúes y el dragón verde; por ejemplo, combinaciones de pungs y chows de 234678 de bambúes.",
    "同一门 1112345678999 加该门任一张牌。": "1112345678999 de un mismo palo más cualquier ficha de ese palo.",
    "四组杠子，剩余一对将牌组成和牌。": "Cuatro kongs y una pareja forman la mano ganadora.",
    "同一门连续七个对子，例如 11223344556677 万。": "Siete parejas consecutivas de un mismo palo, por ejemplo 11223344556677 de caracteres.",
    "一、九万饼条与东南西北中发白各一张，再成一对。": "Una ficha de cada terminal de caracteres, círculos y bambúes y de cada viento y dragón, más otra para formar pareja.",
    "只由万、饼、条的一九牌组成刻子、杠子和将牌。": "Pungs, kongs y pareja formados únicamente por unos y nueves de caracteres, círculos y bambúes.",
    "东南西北中三组刻子或杠子，第四组为对子。": "Tres pungs o kongs de entre Este, Sur, Oeste y Norte; el cuarto viento forma la pareja.",
    "中、发、白中两组刻子，一组对子，另有两组面子。": "Dos pungs y una pareja de dragones rojo, verde y blanco, más otras dos combinaciones.",
    "手牌全部由东南西北中发白组成。": "La mano solo contiene Este, Sur, Oeste, Norte y dragones rojo, verde y blanco.",
    "四组暗刻或暗杠，另有一对将牌。": "Cuatro pungs o kongs ocultos, más una pareja.",
    "一门 112233、556677、99 的七对结构。": "Estructura de siete parejas de un mismo palo: 112233, 556677 y 99.",
    "同一门四组完全相同的顺子，例如四组 123 万。": "Cuatro chows idénticos de un mismo palo, por ejemplo cuatro grupos de 123 de caracteres.",
    "同一门四组连续递增的刻子，例如 111、222、333、444。": "Cuatro pungs consecutivos de un mismo palo, por ejemplo 111, 222, 333 y 444.",
    "同一门四组连续递进的顺子。": "Cuatro chows escalonados de un mismo palo.",
    "三组杠子，另有一组面子和将牌。": "Tres kongs, más una combinación y la pareja.",
    "万、饼、条的一九刻子与字牌刻子混合组成全副牌。": "La mano combina pungs de unos y nueves de caracteres, círculos y bambúes con pungs de honores.",
    "七个不同对子，例如 11223344556677。": "Siete parejas diferentes, por ejemplo 11223344556677.",
    "七张字牌齐全，另有三门各三张不相连序数牌。": "Los siete honores distintos, más tres fichas numerales no consecutivas de cada uno de los tres palos.",
    "全部由 2、4、6、8 序数牌组成的刻子和将牌。": "Pungs y pareja formados únicamente por fichas numerales 2, 4, 6 y 8.",
    "整副牌只使用万、饼或条中的一门。": "Toda la mano usa un único palo: caracteres, círculos o bambúes.",
    "同一门三组完全相同的顺子。": "Tres chows idénticos de un mismo palo.",
    "同一门三组连续递增的刻子。": "Tres pungs consecutivos de un mismo palo.",
    "所有序数牌均为 7、8、9。": "Todas las fichas numerales son 7, 8 y 9.",
    "所有序数牌均为 4、5、6。": "Todas las fichas numerales son 4, 5 y 6.",
    "所有序数牌均为 1、2、3。": "Todas las fichas numerales son 1, 2 y 3.",
    "同一门 123、456、789 三组顺子。": "Tres chows de un mismo palo: 123, 456 y 789.",
    "三门各有 112233、556677、99 的双龙七对结构。": "Estructura de siete parejas de doble dragón con 112233, 556677 y 99 en cada uno de los tres palos.",
    "同一门三组按相同步长递进的顺子。": "Tres chows de un mismo palo que avanzan con el mismo intervalo.",
    "每组面子和将牌都含有 5，例如 123、456、789。": "Cada combinación y la pareja contienen un 5, por ejemplo 123, 456 y 789.",
    "三门各有同一序数的刻子，例如 555 万、555 饼、555 条。": "Un pung del mismo número en cada palo, por ejemplo 555 de caracteres, 555 de círculos y 555 de bambúes.",
    "三组暗刻或暗杠，另有一组面子和将牌。": "Tres pungs o kongs ocultos, más una combinación y la pareja.",
    "三门序数牌互不相连，且不含重复，配字牌组成特殊牌型。": "Jugada especial formada por fichas numerales no consecutivas de los tres palos, sin repeticiones, junto con honores.",
    "三门各取 147、258、369 之一组成组合龙。": "Cada uno de los tres palos aporta uno de los grupos 147, 258 y 369 para formar Fichas cosidas.",
    "全部序数牌均为 6、7、8、9。": "Todas las fichas numerales son 6, 7, 8 y 9.",
    "全部序数牌均为 1、2、3、4。": "Todas las fichas numerales son 1, 2, 3 y 4.",
    "东南西北中任取三组风牌刻子或杠子。": "Tres pungs o kongs de vientos elegidos entre Este, Sur, Oeste y Norte.",
    "三门各有一组相连的顺子，合起来形成 123、456、789。": "Un chow de cada palo que, juntos, forman 123, 456 y 789.",
    "只使用牌面旋转后仍有对应关系的牌，如 123689 饼及白板。": "Solo se usan fichas que mantienen correspondencia al girarlas, como 123689 de círculos y el dragón blanco.",
    "三门各有同一数字的顺子，例如 123 万、123 饼、123 条。": "Un chow con los mismos números en cada palo, por ejemplo 123 de caracteres, 123 de círculos y 123 de bambúes.",
    "三门各有同一数字的刻子，例如 555 万、555 饼、555 条。": "Un pung del mismo número en cada palo, por ejemplo 555 de caracteres, 555 de círculos y 555 de bambúes.",
    "满足和牌条件但全部番种被规则排除，计作无番和。": "La mano cumple las condiciones de victoria, pero las reglas excluyen todas sus jugadas; se puntúa como Mano vacía.",
    "在牌山最后一张自摸和牌。": "Cerrar robando la última ficha del muro.",
    "在牌山最后一张被他家打出后点和。": "Ganar con la última ficha del muro después de que otro jugador la descarte.",
    "杠后从补牌处自摸和牌。": "Cerrar del muro con la ficha de reposición tras un kong.",
    "他家加杠时，和其正在加杠的那张牌。": "Ganar con la ficha que otro jugador está añadiendo a un pung para formar kong.",
    "四组刻子或杠子加一对将牌。": "Cuatro pungs o kongs más una pareja.",
    "一门序数牌加任意字牌组成。": "Fichas numerales de un solo palo junto con honores.",
    "三门顺子按相同步长依次递进。": "Chows de los tres palos que avanzan con el mismo intervalo.",
    "万、饼、条三门和东南西北中发白均有牌。": "Hay fichas de caracteres, círculos y bambúes, y también de Este, Sur, Oeste, Norte y los dragones rojo, verde y blanco.",
    "四组副露面子，最后一张牌单钓并点和。": "Cuatro combinaciones expuestas; se gana por descarte con espera única de pareja.",
