    "剩余张数提示": "Indicar fichas restantes",
    "136张无花牌，0翻可和；吃碰明杠后仅可自摸，打出混儿后本局不可和牌。庄家和牌连庄，其余轮庄。": "136 fichas sin flores; se puede ganar con 0 duplicaciones. Tras chow, pung o kong expuesto solo se puede cerrar del muro. Descartar un hunr impide ganar durante esa mano. El repartidor repite si gana; en otro caso pasa el turno.",
    "可选规则变体（默认关闭）": "Variantes opcionales (desactivadas por defecto)",
    "每张不按本体使用的混儿减1翻，最低保留1翻；原本0翻的和牌仍按0翻结算。": "Cada hunr usado como comodín resta 1 duplicación, con un mínimo de 1. Las victorias que ya tenían 0 duplicaciones siguen puntuando con 0.",
    "阅读北京麻将（吃碰提）完整规则与变体说明": "Leer las reglas completas y variantes del mahjong Pekín (Chi-Peng-Ti)",
    "长春 ·": "Changchun ·",
    "末张单放：": "Última ficha descartada sola:",
    "应付": "Debe pagar",
    "，由座位": "; lo asume el asiento",
    "包庄": "Responsabilidad del repartidor",
    "MIL 2024：136张、十三张手牌，三门带幺九，可吃碰杠和报听。一条仅可在特殊杠中代牌；报听后看宝，六番封顶。三张特殊杠首次不补牌，以后每加一张补一张。": "MIL 2024: 136 fichas, manos de trece; deben incluir los tres palos y terminales u honores. Se permiten chow, pung, kong y declarar espera. El uno de bambúes solo sustituye fichas en kongs especiales. Tras declarar espera se revela el bao; límite de seis fan. Un kong especial de tres fichas no se repone inicialmente; después se repone una ficha por cada ficha añadida.",
    "有效申请后可在5秒内以更高优先级抢断；机器人入座自动关闭": "Tras una solicitud válida, otra de mayor prioridad puede interceptarla durante 5 segundos; se desactiva automáticamente si hay bots sentados",
    "阅读 MIL 长春规则书": "Leer el reglamento MIL de Changchun",
