    "裁切标题图片": "Recortar imagen de portada",
    "拖动图片调整位置，滚轮或滑块缩放。裁切比例与侧栏封面一致（约 2.2:1）。": "Arrastra la imagen para colocarla; usa la rueda o el deslizador para cambiar el tamaño. La proporción coincide con la portada lateral (aprox. 2.2:1).",
    "缩放": "Zoom",
