    "对局形式": "Formato de partida",
    "起始与返点均为40000点，顺位点为0；每副144张，包含8张不同赖子。两副牌组交替使用。": "Puntos iniciales y de retorno: 40000; puntos por posición: 0. Cada juego tiene 144 fichas, incluidos 8 comodines distintos. Se alternan dos juegos de fichas.",
    "阅读夺彩麻将规则书与赖子图鉴": "Leer el reglamento de Duocai y el catálogo de comodines",
    "清空全部": "Borrar todo",
    "四家均预置 13 张手牌、8 张固定牌墙，另设 24 张公共牌墙。庄家开牌首摸取自固定墙；一家摸空后，剩余固定牌按东南西北接到公共墙前。": "Cada jugador tiene 13 fichas iniciales y un muro fijo de 8; además hay un muro común de 24. El primer robo del repartidor procede de su muro fijo. Cuando un jugador agota su muro, las fichas fijas restantes se añaden al principio del muro común en orden Este, Sur, Oeste y Norte.",
    "四家均预置 13 张手牌、14 张个人牌墙。庄家开牌首摸取自个人牌墙。无公共牌墙，不预先把庄家第一张摸牌放入手牌。": "Cada jugador tiene 13 fichas iniciales y un muro personal de 14. El primer robo del repartidor procede de su muro personal. No hay muro común ni se añade previamente el primer robo del repartidor a su mano.",
    "副：": "Reparto:",
    "家坐庄。牌墙从第 1 张开始依次摸取。": "es el repartidor. Se roba del muro por orden desde la ficha 1.",
