    "自动匹配": "Emparejamiento automático",
    "在线玩家按准备时间依次匹配，凑够 4 人自动组桌并开局。使用所选配置的最新设置，正在进行的对局不受修改影响。": "Los jugadores conectados se emparejan por orden de preparación. Al reunir 4, se crea la mesa y empieza la partida automáticamente. Se usa la última versión de la configuración seleccionada; los cambios no afectan a las partidas en curso.",
