    "已保存的设置发生更新，当前草稿仍保留。请核对后再保存，或取消修改以载入最新设置。": "La configuración guardada ha cambiado; se conserva el borrador actual. Revísalo antes de guardar o cancela los cambios para cargar la última versión.",
    "该预设已被删除，草稿仍保留。请选择其他配置，或复制内容后新建预设。": "Se ha eliminado este preajuste; se conserva el borrador. Elige otra configuración o copia el contenido para crear un preajuste nuevo.",
