    "MIL 贵州麻将（推广）2023：108张，无花无癞子，不吃。报听、鸡杠、查叫与39分封顶采用同一标准规。": "Mahjong Guizhou MIL (promocional) 2023: 108 fichas, sin flores ni comodines, sin chow. Declarar espera, gallos, kongs, comprobación de espera y límite de 39 puntos siguen el mismo reglamento estándar.",
