    "起和点数": "Puntos mínimos para ganar",
    "只允许碰彩虹，不允许普通碰牌。每位玩家每局最多补牌两次。无色牌可组成对子或同色顺子，不能组成刻子或彩虹。": "Solo se permite reclamar grupos arcoíris, no grupos ordinarios del mismo número. Cada jugador puede reponer como máximo dos veces por mano. Las fichas incoloras pueden formar parejas o secuencias de un color, pero no grupos del mismo número ni arcoíris.",
    "阅读完整规则书": "Leer el reglamento completo",
    "· 中": "· Aciertos:",
    "鸟（每家另付": "pájaros (cada jugador paga además",
    "分）": "puntos)",
    "和牌张按": "La ficha ganadora se puntúa como",
    "MIL 2024：112张、十三张手牌，红中为万能牌，仅可自摸；可碰杠，不吃。最高四番，和牌后扎两鸟，流局退杠。": "MIL 2024: 112 fichas, manos de trece; el dragón rojo es comodín y solo se puede cerrar del muro. Se permiten pung y kong, sin chow. Máximo de cuatro fan; se sacan dos pájaros al ganar y se devuelven los pagos de kong si la mano es nula.",
    "阅读 MIL 红中规则书": "Leer el reglamento MIL de Hongzhong",
    "九江麻将是九江地区一个没落的麻将规则，目前九江地区通行红中麻将，本规则是芋蔗凭借小时候的记忆和一定程度上的改良复现的一种失传规则，如发现任何问题或者能够提供九江麻将的资料的玩家可以联系Q2264033554": "El mahjong Jiujiang es un reglamento local en desuso, ya que actualmente predomina el Hongzhong en la región. 芋蔗 lo ha recuperado de sus recuerdos de infancia, con algunas modificaciones. Si encuentras problemas o puedes aportar información sobre el mahjong Jiujiang, contacta con QQ 2264033554.",
    "下载九江麻将规则书": "Descargar reglamento de mahjong Jiujiang",
    "回复": "Responder",
    "加载回复…": "Cargando respuestas…",
    "暂无回复": "No hay respuestas",
    "写下回复…": "Escribe una respuesta…",
    "传统84张，东南西三席，5番起和。飞可作百搭或当花；花套与杠即时结算，和牌后另比输家花分与三家飞牌。": "84 fichas tradicionales y tres asientos: Este, Sur y Oeste. Mínimo de 5 fan. El fei puede ser comodín o flor. Los conjuntos de flores y kongs se pagan al instante; tras una victoria se comparan además las flores de los perdedores y los fei de los tres jugadores.",
