    "阅读上饶麻将 规则书": "Leer el reglamento de mahjong Shangrao",
    "山西麻将 · MIL试行2023版。136张、十三张手牌、无花无癞子；须暗扣报听，有和必和，和牌时结杠。": "Mahjong Shanxi · Edición provisional MIL 2023. 136 fichas, manos de trece, sin flores ni comodines. Hay que declarar espera con un descarte boca abajo y ganar si es posible; los kongs se liquidan al ganar.",
    "局时是每局额外思考储备，默认20秒；每次操作先使用步时，默认5秒。零局时只使用步时。": "El tiempo por mano es una reserva adicional para pensar, de 20 segundos por defecto. Cada acción consume primero su tiempo propio, de 5 segundos por defecto. Con reserva cero solo se usa el tiempo por acción.",
    "MIL 沈阳（2025）": "Shenyang MIL (2025)",
    "四川子规则": "Variante de Sichuan",
    "血流成河·弃三张": "Río de sangre (descarte de tres)",
    "血流成河（换三张）": "Río de sangre (intercambio de tres)",
    "每盘副数": "Repartos por partida",
    "SPGG 2024 四人麻将：148张牌，1台起和、5台封顶，400分起分。花季与动物婚配、杠即时支付，庄家和牌或无杠流局连庄。": "Mahjong de cuatro jugadores SPGG 2024: 148 fichas, mínimo de 1 tai, máximo de 5 tai y 400 puntos iniciales. Las parejas de flores, estaciones y animales y los kongs se pagan al instante. El repartidor repite si gana o si la mano termina nula sin kongs.",
    "查看平台规则及原文来源": "Ver reglas de la plataforma y fuentes originales",
