    "支持本赛事／基地的手动牌山、复现牌山、密钥牌山；规则须与房间一致。": "Admite muros manuales, recreados y por clave de este torneo o club; sus reglas deben coincidir con las de la sala.",
    "自动生成复式密钥": "Generar clave de duplicado automáticamente",
    "每个房间生成并绑定一个独立密钥，本次创建": "Se genera y vincula una clave independiente para cada sala; se crearán",
    "个密钥。花牌使用上方设置，局数跟随密钥。": "claves. Las flores siguen la configuración anterior y las manos, la clave.",
    "今日已创建": "Creadas hoy:",
    "个，剩余": "; quedan",
    "个；可保存": "; se pueden conservar",
    "个。额度由场馆管理员共用，北京时间零点刷新。": ". Los administradores del espacio comparten el cupo, que se renueva a medianoche, hora de Pekín.",
    "阅读温州 MIL 2024 规则书": "Leer el reglamento MIL de Wenzhou 2024",
    "MIL 2025：136张，皮癞单张杠；必须开口，逐家六番起和。末四张只能自摸或过，七皮、十杠途中结算，轮庄。鸣牌响应为3秒。": "MIL 2025: 136 fichas; indicador y comodín pueden declararse como kong de una ficha. Es obligatorio abrir la mano y alcanzar seis fan contra cada rival. Con las últimas cuatro fichas solo se puede cerrar del muro o pasar. Siete indicadores y diez kongs provocan liquidación anticipada; el repartidor rota. Hay 3 segundos para responder a llamadas.",
    "阅读 MIL 武汉规则书": "Leer el reglamento MIL de Wuhan",
    "144张、十三张手牌；可吃碰杠，逐张补花。2花自摸、3花放冲、1花独吊；固定牌型已含胡牌底花。": "144 fichas, manos de trece; se permiten chow, pung y kong y las flores se reponen de una en una. Se necesitan 2 flores para cerrar del muro, 3 para ganar por descarte y 1 para espera única. Las jugadas fijas ya incluyen las flores base de victoria.",
    "阅读宜兴规则书": "Leer el reglamento de Yixing",
