    "例如：第一轮 · A 组": "Ejemplo: ronda uno · Grupo A",
    "川麻牌山布局": "Distribución del muro de Sichuan",
    "庄家也只预置 13 张，开牌时再从自己的牌墙头摸一张。东南西北方位固定，庄家依次轮转。": "El repartidor también empieza con solo 13 fichas y roba una del principio de su muro al comenzar. Los asientos Este, Sur, Oeste y Norte son fijos; el repartidor rota por orden.",
    "牌山类型": "Tipo de muro",
    "1–128 个字符的文本种子": "Semilla de texto de 1–128 caracteres",
    "一个种子生成整场牌山。相同规则、花牌设置、局数和种子生成相同的手牌与牌山。": "Una semilla genera los muros de toda la partida. Con las mismas reglas, flores, manos y semilla se obtienen las mismas manos iniciales y muros.",
