    "分享美术资源规约": "Normas para compartir recursos gráficos",
    "上传内容须由你拥有版权，或取得明确允许非商业使用和公开分享的许可证。": "Debes ser titular de los derechos del contenido o tener una licencia que permita expresamente su uso no comercial y su difusión pública.",
    "没有版权或许可证的资源只能私下使用，不能上传到平台分享站。": "Los recursos sin derechos o licencia solo pueden usarse en privado; no pueden subirse al sitio de recursos compartidos de la plataforma.",
