    "修改": "Editar",
    "查看已解除锁定的密钥、创建时间、解锁时间和关联对局。": "Consulta las claves desbloqueadas, sus fechas de creación y desbloqueo y las partidas vinculadas.",
    "创建复式密钥 →": "Crear clave de duplicado →",
    "输入复式密钥；留空查看最近解除锁定的密钥": "Introduce una clave de duplicado; vacío para ver las últimas claves desbloqueadas",
    "锁定的密钥不公开。解除锁定后可在这里查询，且不能重新锁定。复式对局不保存本地牌谱。": "Las claves bloqueadas no son públicas. Tras desbloquearlas se pueden consultar aquí y no se pueden volver a bloquear. Las partidas de duplicado no guardan registros locales.",
    "创建者 / 所属赛事": "Creador / torneo",
