    "初始 R 为 1500，仅系统匹配计分，自建房不计。": "La R inicial es 1500. Solo puntúa el emparejamiento del sistema, no las salas personalizadas.",
    "预期胜率 = 1 / (1 + 10^((对手 R − 自己 R) / 2000))。": "Probabilidad de victoria = 1 / (1 + 10^((R del rival − R propia) / 2000)).",
    "变化值 = 32 ×（实际结果 − 预期胜率），结果四舍五入为整数；胜为 1，负为 0。": "Cambio = 32 × (resultado real − probabilidad de victoria), redondeado al entero más cercano; victoria = 1, derrota = 0.",
    "历史积分按迁移前原分 + 500 修正，之后已结算的积分变化、胜负和场数保留。": "La puntuación histórica se ajusta sumando 500 al valor anterior a la migración. Se conservan los cambios posteriores ya liquidados, las victorias, las derrotas y el número de partidas.",
