    "点击下方牌面添加手牌；点击副露框后，只有能组成合法牌组的牌会高亮可点。 手牌 + 副露合计最多 14 张，所有牌必须分成 3 张及以上的合法牌组，无雀头。 自摸支持连续加杠预测；手牌为空时也可输入副露，查看可摸入的和牌张。": "Pulsa las fichas de abajo para añadirlas a la mano. Al seleccionar un recuadro de grupo expuesto, solo se resaltan las fichas que permiten formar un grupo válido. Mano y grupos expuestos suman como máximo 14 fichas; todas deben formar grupos válidos de 3 o más, sin pareja. La victoria del muro admite previsión de ampliaciones consecutivas de grupos. También puedes introducir grupos expuestos con la mano vacía para ver qué robos permiten ganar.",
