    "种）": "tipos)",
    "“仅自摸”需摸入后按顺序加杠；其他玩家的弃牌不能用于这种和法。展开查看加杠步骤与最终牌型。": "«Solo cerrar del muro» exige robar y luego ampliar grupos en el orden indicado; no se puede usar un descarte rival para esta victoria. Despliega para ver los pasos de ampliación y la mano final.",
    "仅自摸 ·": "Solo cerrar del muro ·",
