    "；和牌": "; victoria",
    "12/13 张显示向听与进张效率，14 张显示切牌效率。 已和牌仍会列出可继续扩展的进张；一向听、两向听、三向听及以上都会计算能减少向听的进张。 每种牌只有一张。输入为空时随机生成 14 张。计算在浏览器本地完成。": "Con 12/13 fichas se muestran shanten y eficacia de mejora; con 14, eficacia de descarte. Aunque la mano ya gane, se indican los robos que permiten ampliarla. Para uno, dos y tres o más shanten se calculan los robos que reducen el shanten. Solo hay una ficha de cada tipo. Si la entrada está vacía, se generan 14 fichas aleatorias. El cálculo se realiza localmente en el navegador.",
