    "选出一个番种（如凑番和、小三元），搜索出和出该番的所有牌谱，并且提供牌谱链接。": "Selecciona una jugada, como Victoria por suma de jugadas o Tres pequeños dragones, para buscar todos los registros donde se haya conseguido, con sus enlaces.",
    "选择番种": "Seleccionar jugada",
    "国标巡目按庄家巡计算，与对局进程一致。顺位按牌谱得分独立计算，允许同分同排位。": "Los turnos de MCR se cuentan por el repartidor, de acuerdo con el transcurso de la mano. Las posiciones se calculan independientemente según los puntos del registro y permiten compartir puesto en caso de empate.",
    "以下统计仅覆盖当前筛选内已下载的牌谱。条件比率使用对应的立直、副露或和牌样本；无样本时显示“—”。各指标可查看计算口径。": "Estas estadísticas solo incluyen los registros descargados del filtro actual. Las tasas condicionales usan las muestras correspondientes de riichi, manos abiertas o victorias; si no hay muestra se indica «—». Puedes consultar cómo se calcula cada indicador.",
