    "四人真人匹配场每完成一小局，注册玩家获得 0.10 萨拉币（含连庄）": "Al completar cada mano de emparejamiento entre cuatro personas, los jugadores registrados reciben 0.10 monedas Salasasa (incluidas las repeticiones del repartidor)",
    "在匹配对局中每完成一小局，获得0.05个萨拉币，例如国标麻将全庄战一共16小局，对局结束后获得0.8萨拉币。": "Cada mano completada en una partida de emparejamiento otorga 0.05 monedas Salasasa. Por ejemplo, una partida MCR de cuatro rondas consta de 16 manos y concede 0.8 monedas Salasasa al terminar.",
    "游客无法购买物品": "Los invitados no pueden comprar objetos",
    "商店同步超时，请重新打开商店": "Tiempo de sincronización de la tienda agotado. Vuelve a abrirla.",
    "商店请求失败，请重新打开商店": "Error en la solicitud a la tienda. Vuelve a abrirla.",
    "商品已下架，请重新打开商店": "El producto ya no está a la venta. Vuelve a abrir la tienda.",
    "商品价格已更新，请重新打开商店后购买": "El precio ha cambiado. Vuelve a abrir la tienda antes de comprar.",
    "已拥有此物品或数量无效，不能重复购买": "Ya tienes este objeto o la cantidad no es válida; no se puede repetir la compra",
    "复制校验码": "Copiar código de verificación",
    "已复制校验码": "Código de verificación copiado",
    "承诺": "Compromiso",
    "盐": "Sal",
    "真实时间": "Tiempo real",
    "第二等待时间": "Segundo tiempo de espera",
    "等待下一位玩家摸牌": "Esperando el robo del siguiente jugador",
    "真实时间仅支持川麻复式": "El tiempo real solo está disponible en duplicado Sichuan",
    "第二等待时间必须为3、5、8、10、15或20秒": "El segundo tiempo de espera debe ser de 3, 5, 8, 10, 15 o 20 segundos",
    "真实时间：其他玩家出牌后，如果下一位应由你摸牌，碰、明杠或和牌使用正常局时与步时；否则使用第二等待时间。第二等待时间结束后，牌局不再专门等待你，但本张弃牌尚未处理完时，仍可操作。第二等待时间也用于战术鸣牌的抢断询问。血战有人和牌退场后，按仍在行牌的顺序判断。": "Tiempo real: tras un descarte ajeno, si te corresponde el siguiente robo, usas el tiempo normal de mano y acción para pung, kong expuesto o victoria; si no, usas el segundo tiempo de espera. Al agotarse, la partida deja de esperarte en exclusiva, pero aún puedes actuar mientras ese descarte no se haya resuelto. Este tiempo también se usa para consultas de intercepción de llamadas tácticas. En batalla hasta el final, tras retirarse un ganador se sigue el orden de quienes continúan jugando.",
    "非下一位摸牌者的首次响应等待与战术鸣牌抢断询问共用此时长，不扣局时。关闭真实时间会保留所选秒数，战术鸣牌开启时继续使用。首次等待结束仍可操作；抢断询问到期后执行已确定的动作。": "Este tiempo se comparte entre la primera espera de respuesta de quien no debe robar a continuación y la consulta de intercepción de llamadas tácticas; no consume la reserva de mano. Desactivar el tiempo real conserva los segundos elegidos, que siguen usándose con llamadas tácticas. Se puede actuar tras la primera espera; al vencer la consulta de intercepción se ejecuta la acción ya determinada.",
