    "免费Apple账户安装说明": "Instalación con cuenta gratuita de Apple",
    "IPA下载后需要签名安装，不能直接在Safari中点击文件完成安装。": "Tras descargar el IPA, debes firmarlo para instalarlo. No basta con abrir el archivo en Safari.",
    "准备免费Apple账户、iPhone或iPad，以及一台Windows或Mac电脑。": "Necesitas una cuenta gratuita de Apple, un iPhone o iPad y un ordenador Windows o Mac.",
    "在电脑上安装": "Instala en el ordenador",
    "，连接设备并信任电脑，将本站发布的IPA导入工具。": ", conecta el dispositivo, autoriza el ordenador e importa el IPA de esta web en la herramienta.",
    "在签名工具中使用自己的Apple账户完成安装，并按设备提示信任开发者、开启开发者模式。": "Usa tu propia cuenta de Apple en la herramienta de firma para instalarlo. Sigue las indicaciones del dispositivo para confiar en el desarrollador y activar el modo de desarrollador.",
    "免费签名通常有效7天，到期前需通过侧载工具刷新签名。游戏没有更新时也需要续签；应用内资源更新不能延长签名期限。": "La firma gratuita suele durar 7 días. Debes renovarla con la herramienta de instalación antes de que caduque, aunque el juego no haya cambiado. Las actualizaciones de recursos dentro de la aplicación no prolongan la firma.",
    "Apple账户密码和验证码只在你使用的签名工具中输入，本站不会收集。": "Introduce tu contraseña de Apple y los códigos de verificación solo en la herramienta de firma que uses. Esta web no los recopila.",
