    "恋绘色版本：《香港新章规则书》，默认144张、三番起和、十三番封顶、全铳制；庄和或流局连庄，不设报听。": "Versión de Lianhuise, «Reglamento de nuevas reglas de Hong Kong»: por defecto, 144 fichas, mínimo 3 fan, máximo 13 fan y pago completo de quien da el descarte ganador. El repartidor repite si gana o no hay ganador. No se declara espera.",
    "香港麻雀协会《香港麻雀总例》：三番起糊，十番封顶，每局轮庄。": "«Reglamento general de mahjong de Hong Kong», de la Asociación de Mahjong de Hong Kong: mínimo 3 fan, máximo 10 fan y cambio de repartidor cada mano.",
    "Wiki版本：规则资料见 Mahjong Wiki 的 IGS 分栏。136张，支持七对子与报听。": "Versión Wiki: consulta la columna IGS de Mahjong Wiki. 136 fichas; admite siete parejas y declaración de espera.",
