    "夺彩麻将，由自恧发起，和雀庄的小伙伴们共同打磨的一款麻将游戏子规则，X计划的开山之作。": "Mahjong Duocai es una variante iniciada por Ziniu y desarrollada junto con sus compañeros del salón de mahjong. Es la primera creación del Proyecto X.",
    "夺彩麻将规则书与赖子图鉴": "Reglamento y catálogo de comodines de Mahjong Duocai",
