    "恋绘色《香港新章规则书》。": "«Reglamento de nuevas reglas de Hong Kong», de Lianhuise.",
    "《香港新派清章（恋绘色魔改版）》原文。": "Original de «Reglas antiguas de Hong Kong con enfoque nuevo (variante de Lianhuise)».",
    "香港麻雀协会《港式十六张新章麻雀总例》详述版。": "Versión detallada del «Reglamento general de nuevas reglas de mahjong de dieciséis fichas de Hong Kong», de la Asociación de Mahjong de Hong Kong.",
    "虹雀² v1.7": "Hongque² v1.7",
    "虹雀² v1.7 规则书": "Reglamento Hongque² v1.7",
    "虹雀² v1.7 规则书，包含基本规则、番种说明及牌例。": "Reglamento Hongque² v1.7, con reglas básicas, jugadas y ejemplos.",
    "虹雀 W v1.1": "Hongque W v1.1",
