    "未分类": "Sin categoría",
    "归类规则": "Reglas de clasificación",
    "其他资料": "Otros materiales",
    "规则研究、牌例与来自 other 文件夹的资料索引": "Investigaciones, ejemplos e índice de materiales de la carpeta other",
    "提交资料": "Aportar material",
    "提交新的规则书、牌例或规则研究资料": "Enviar nuevos reglamentos, ejemplos o investigaciones sobre reglas",
    "十六张手牌，全部字牌及八花补花，开金、抢金、听金坎、一游及二游；动态留墩，最后四张只摸不打。": "Manos de dieciséis fichas, todos los honores y reposición de ocho flores. Incluye revelar oro, robar oro, espera central de oro, Primer paseo y Segundo paseo. La reserva del muro es variable; las últimas cuatro fichas se roban sin descartar.",
    "福州麻将规则与平台补则": "Reglas de Fuzhou y suplementos de la plataforma",
    "福州麻将规则书原文": "Reglamento original de mahjong Fuzhou",
    "SPGG 2024：148张，1台起和、5台封顶，花季与动物婚配即时支付；含平台补充约定。": "SPGG 2024: 148 fichas, mínimo 1 tai y máximo 5 tai; pago inmediato por flores, estaciones y parejas de animales. Incluye acuerdos adicionales de la plataforma.",
    "新加坡 SPGG 平台规则": "Reglas SPGG de Singapur en la plataforma",
    "完整规则说明、计分及补充口径。": "Reglas completas, puntuación y criterios adicionales.",
    "SPGG 2024 英文原文": "Original en inglés de SPGG 2024",
    "Singapore Polytechnic Graduates Guild 发布。": "Publicado por Singapore Polytechnic Graduates Guild.",
    "九江麻将规则书": "Reglamento de mahjong Jiujiang",
    "芋蔗提供的更新版规则书。": "Reglamento actualizado facilitado por Yuzhe.",
    "宜兴麻将是江苏宜兴本地的特色玩法，由144张牌组成，其中万条筒各36张，东南西北中发白各4张，花牌8张，2花自摸，3花放冲，一花独吊，最先将手牌全部组成顺子和刻子的玩家赢得一局，起手花牌数能决定你当前牌局打法规划，牌局种类门清，碰碰胡，混一色，清一色等常见大牌，还包括独吊翻倍，杠开翻倍，海底翻倍，抢杠翻3倍等特殊机制，游戏尚在测试阶段，如对本规则感兴趣或有任何建议都可以添加Q541784531一同交流": "El mahjong de Yixing, Jiangsu, utiliza 144 fichas: 36 de caracteres, 36 de bambúes, 36 de círculos, cuatro de cada viento y dragón y ocho flores. Con 2 flores se puede ganar del muro, con 3 con un descarte y con 1 en espera única. Gana quien primero agrupa toda su mano en chows y pungs. Las flores iniciales orientan la estrategia. Incluye grandes manos como Mano oculta, Todo pung, Mano semipura y Mano pura, además de doble valor por espera única, victoria tras kong o última ficha, y triple por robo de kong. Está en pruebas. Si te interesa o tienes sugerencias, contacta por QQ con 541784531.",
    "宜兴麻将规则书": "Reglamento de mahjong Yixing",
    "宜兴麻将规则书（最新 Word）": "Reglamento de Yixing (Word actualizado)",
