    "在线玩国标麻将 MCR：免费网页对战 | Salasasa": "Juega a mahjong MCR en línea: partidas web gratis | Salasasa",
    "在 Salasasa 浏览器中免费进行四人国标麻将 MCR 对局，支持自动算番、段位匹配、自定义房间和牌谱复盘，无需下载客户端。": "Juega gratis a mahjong MCR de cuatro jugadores en el navegador de Salasasa, con puntuación automática, emparejamiento clasificatorio, salas personalizadas y repeticiones, sin descargar el cliente.",
    "麻将规则比较：国标、立直、台湾、四川与长沙 | Salasasa": "Comparación de reglas: MCR, riichi, Taiwán, Sichuan y Changsha | Salasasa",
    "比较国标 MCR、立直、台湾、四川与长沙麻将，阅读规则入门和原始规则书，并找到对应的 Salasasa 对局客户端。": "Compara mahjong MCR, riichi, taiwanés, de Sichuan y de Changsha; lee introducciones y reglamentos originales y encuentra el cliente de Salasasa correspondiente.",
    "国标麻将 MCR 规则入门：81 番种与 8 番起和 | Salasasa": "Introducción a MCR: 81 jugadas y mínimo de 8 puntos | Salasasa",
    "了解国标麻将 MCR 的基本和牌结构、81 番种、8 番起和要求及与立直的区别，查阅规则书并进入 Salasasa 网页对局。": "Conoce la estructura básica de las manos ganadoras de MCR, sus 81 jugadas, el mínimo de 8 puntos y las diferencias con riichi; consulta el reglamento y entra en las partidas web de Salasasa.",
    "Salasasa 玩家指南：在线国标麻将、对局与复盘": "Guía de Salasasa: mahjong MCR en línea, partidas y repeticiones",
    "从注册和进入 2D 大厅开始，了解 Salasasa 国标麻将的段位场、自定义房间、鸣牌保护、战术鸣牌、牌谱复盘、算番练习和随机种子验证。": "Desde el registro y el vestíbulo 2D, conoce las salas clasificatorias y personalizadas de MCR de Salasasa, la protección y las reclamaciones tácticas, las repeticiones, la práctica de puntuación y la verificación de semillas.",
    "国标麻将,立直麻将,长沙麻将,四川麻将,台湾麻将,在线麻将,麻将平台,麻将计算器,麻将规则,Salasasa": "mahjong MCR,mahjong riichi,mahjong de Changsha,mahjong de Sichuan,mahjong taiwanés,mahjong en línea,plataforma de mahjong,calculadora de mahjong,reglas de mahjong,Salasasa",
    "汇集国标麻将（新编 MCR）、立直麻将、青雀、虹雀² 等规则书 PDF，可在线阅读或下载，附规则介绍与牌例。": "Reúne reglamentos PDF de MCR revisadas, riichi, Qingque, Hongque² y más, para leer en línea o descargar, con introducciones y ejemplos de manos.",
    "麻将规则,国标麻将规则,立直麻将规则,青雀规则,虹雀²,规则书PDF": "reglas de mahjong,reglas de MCR,reglas de riichi,reglas de Qingque,Hongque²,reglamentos PDF",
    "麻将规则书 - Salasasa": "Reglamentos de mahjong - Salasasa",
    "查阅各麻将规则的规则书 PDF、牌例与文档，可在线阅读或下载。": "Consulta reglamentos PDF, ejemplos de manos y documentos de distintas variantes para leer en línea o descargar.",
    "麻将规则书,麻将规则,规则书PDF": "reglamentos de mahjong,reglas de mahjong,reglamentos PDF",
    "开放收录的麻将规则与资料馆：麻将谱系、可对局规则、MIL 竞赛规则、地方与自制规则，附讨论区。": "Biblioteca abierta de reglas y materiales de mahjong: genealogía, variantes jugables, reglas de competición MIL y reglas regionales y originales, con foro de debate.",
    "麻雀图书馆,麻将规则资料,麻将规则书,麻将牌例": "biblioteca de mahjong,materiales de reglas,reglamentos de mahjong,ejemplos de manos",
    "查阅各麻将规则的规则书 PDF、牌例与讨论，可在线阅读或下载。": "Consulta reglamentos PDF, ejemplos de manos y debates sobre distintas variantes, en línea o descargables.",
    "麻将规则书,麻将规则,麻将牌例,麻将资料": "reglamentos de mahjong,reglas de mahjong,ejemplos de manos,materiales de mahjong",
