    "麻将年代表：纸牌、牌九接到宁波麻将再分化。": "Cronología del mahjong: de los naipes y el pai gow al mahjong de Ningbo y sus ramificaciones.",
    "麻将谱系,麻将分类,麻将年代表,国标麻将,四川麻将,东北麻将": "genealogía del mahjong,clasificación del mahjong,cronología del mahjong,mahjong MCR,mahjong de Sichuan,mahjong del noreste de China",
