    "麻将谱系,麻将分类,麻将关系表,国标麻将,四川麻将,东北麻将": "genealogía del mahjong,clasificación del mahjong,relaciones del mahjong,mahjong MCR,mahjong de Sichuan,mahjong del noreste de China",
    "按源链接与原文摘录归档的麻将规则研究资料，保留出处，便于查证与对比。": "Materiales de investigación de reglas archivados por enlaces y extractos originales, con sus fuentes para facilitar la comprobación y comparación.",
    "麻将规则资料,规则研究,麻将规则原文,规则归档": "materiales de reglas de mahjong,investigación de reglas,textos originales de reglas,archivo de reglas",
    "规则资料搜集：麻将规则原文 - Salasasa": "Recopilación de fuentes: reglas originales de mahjong - Salasasa",
    "在线国标麻将算番工具：输入手牌、副露与和牌方式，自动计算番种、得分及全部和牌拆解。": "Calculadora MCR en línea: introduce mano, combinaciones expuestas y forma de victoria para calcular jugadas, puntos y todas las descomposiciones ganadoras.",
    "国标麻将算番,国标麻将计算器,麻将番数计算,国标麻将和牌": "puntuación de mahjong MCR,calculadora MCR,cálculo de puntos de mahjong,victoria MCR",
    "按虹雀² v1.7 规则在线计算和牌拆解与番数得分，支持手牌与副露输入。": "Calcula en línea las descomposiciones y la puntuación de Hongque² v1.7, con entrada de mano y grupos expuestos.",
    "虹雀²,虹雀²计算器,麻将和牌计算器,麻将算番": "Hongque²,calculadora Hongque²,calculadora de victoria de mahjong,puntuación de mahjong",
    "输入 13 张手牌分析听牌与进张，14 张分析最佳切牌，支持七对、十三幺、全不靠等和牌牌型。": "Introduce 13 fichas para analizar esperas y mejoras, o 14 para encontrar el mejor descarte; admite siete parejas, trece huérfanos, fichas cosidas con pocos honores y otras formas.",
    "麻将牌理,听牌分析,进张,切牌建议,向听数": "análisis de mahjong,análisis de esperas,fichas de mejora,sugerencias de descarte,shanten",
    "用对局公布的主种子在浏览器内复现随机座位与每局配牌、牌山，验证服务器未中途更换随机种子。": "Reproduce en el navegador los asientos aleatorios, repartos y muros con la semilla maestra publicada para comprobar que el servidor no la cambió durante la partida.",
