    "当前浏览器不支持 DecompressionStream，无法解压雀渣 script": "Este navegador no admite DecompressionStream; no se puede descomprimir el script de Quezha",
    "当前浏览器不支持 CompressionStream，无法压缩雀渣 script": "Este navegador no admite CompressionStream; no se puede comprimir el script de Quezha",
    "这是 salasasa 牌谱，请选择 salasasa → 雀渣": "Este es un registro de salasasa. Elige salasasa → Quezha.",
