    "已 zlib+base64；可用 step_decoded 查看": "Ya está en zlib+base64; consulta step_decoded para verlo",
    "近似转换：骰子、实例 ID、摸牌座位由牌谱推算。": "Conversión aproximada: dados, ID de ejemplar y asiento de robo se deducen del registro.",
    "开发模式：下载不限局数。": "Modo de desarrollo: descarga sin límite de manos.",
    "下载牌谱": "Descargar registros",
    "四人立直": "Riichi de cuatro jugadores",
    "三人立直": "Riichi de tres jugadores",
    "起始点数须为 1000–1000000 之间的整数，且为 100 的倍数": "Los puntos iniciales deben ser un entero entre 1000 y 1000000, múltiplo de 100",
    "未知日麻详细规则": "Regla detallada de Riichi desconocida",
    "请选择有效的立直子规则": "Selecciona una variante válida de Riichi",
    "三人顺位点和2000点不听罚符仅适用于三人立直": "Los puntos por posición de tres jugadores y la penalización de noten de 2000 puntos solo se aplican a Riichi de tres jugadores",
    "固定分差2000点不听罚符仅适用于四人立直": "La penalización de noten con diferencia fija de 2000 puntos solo se aplica a Riichi de cuatro jugadores",
    "起和番须为 1–64 的整数（不含宝牌）": "El mínimo para ganar debe ser un entero de 1–64 han (sin dora)",
    "请选择有效的起和线": "Selecciona un umbral de victoria válido",
    "这组青雀番种尚无精算数据，请调整手牌后重试。": "Esta combinación de jugadas Qingque aún no tiene datos actuariales. Ajusta la mano y reintenta.",
    "请输入主种子": "Introduce la semilla principal",
    "主种子格式错误：仅支持十进制或十六进制": "Formato de semilla principal incorrecto: solo se admite decimal o hexadecimal",
    "上饶麻将是流行于江西上饶及周边的玩法，使用136张麻将牌（无花牌），只能自摸。除了基本的屁和牌型，还有碰碰胡、七对、九幺和十三烂特色牌型。宝牌（即“癞子”）为核心特色，单宝仅可作将，多余宝才能作万能牌，打出宝牌（“飞宝”）和牌可翻倍，因此又称为“飞宝麻将”。特色牌型和翻倍机制配合只能自摸的规则，使牌局兼具趣味性和策略性。": "El mahjong Shangrao se juega en Shangrao, Jiangxi, y sus alrededores. Usa 136 fichas sin flores y solo permite cerrar del muro. Además de manos básicas, incluye Todo pung, Siete parejas, Todo terminales y honores y Trece inconexas. Su elemento central es el bao o comodín: un único bao solo puede formar pareja; los adicionales sí son comodines universales. Descartarlo («bao volador») puede duplicar la victoria, por lo que también se llama «mahjong del bao volador». Estas jugadas y duplicaciones, junto con la obligación de cerrar del muro, aportan diversión y estrategia.",
    "飞宝七星": "Bao volador de siete estrellas",
    "请选择上饶麻将标准规则": "Selecciona las reglas estándar de mahjong Shangrao",
    "副数组": "Grupos de puntos básicos",
    "房间名不能超过128字": "El nombre de sala no puede superar 128 caracteres",
    "MIL 沈阳麻将（推广）2025：136张，须有刻子或将牌为中发白、有幺九、齐三门或纯一色；七对例外。喜杠、旋风杠和杠后公示，六番封顶，最后四张分张自摸。": "Mahjong Shenyang MIL (promocional) 2025: 136 fichas. Se necesita un pung o pareja de dragones, terminales u honores y los tres palos o un solo palo puro; Siete parejas es una excepción. Incluye kong de dragones, kong de vientos y exposición tras kong. Límite de seis fan; las últimas cuatro fichas se roban por separado y solo permiten cerrar del muro.",
    "沈阳麻将仅支持 MIL 2025": "Mahjong Shenyang solo admite MIL 2025",
    "训练牌山：直接输入随机种子或随机生成随机种子，允许观战，不使用复式密钥": "Muro de entrenamiento: introduce una semilla o genera una aleatoria. Permite espectadores y no usa clave de duplicado.",
    "密钥牌山：自动生成随机种子生成牌墙，构建后的手牌在首次使用时，玩家和密钥创建者均不可知": "Muro por clave: una semilla aleatoria genera el muro. Al usarse por primera vez, ni los jugadores ni el creador de la clave conocen las manos.",
    "复现牌山：使用已经确定的随机种子构建手牌和牌山，密钥创建者了解牌山的具体内容": "Muro recreado: una semilla ya determinada genera las manos y el muro; el creador de la clave conoce su contenido.",
    "手动牌山：使用手动设牌构建的牌山，密钥创建者了解牌山的具体内容，一般复原线下对局时使用": "Muro manual: construido colocando fichas manualmente; el creador conoce su contenido. Se usa normalmente para recrear partidas presenciales.",
    "请先选择密钥牌山并切换到输入已有密钥": "Selecciona primero muro por clave y cambia a introducir una clave existente",
