    "操作结果暂时无法确认，请重试": "No se puede confirmar el resultado temporalmente. Reintenta.",
    "全部邮件": "Todos los mensajes",
    "邮件暂时无法加载，请重试": "No se pueden cargar los mensajes temporalmente. Reintenta.",
    "领取结果暂时无法确认，请再次领取核实，物品不会重复发放": "No se puede confirmar la reclamación temporalmente. Reclama de nuevo para comprobarla; los objetos no se entregarán dos veces.",
    "个人资料暂时无法加载": "No se puede cargar el perfil temporalmente",
    "上传格式 上传一个 .zip，直接放一套按牌面代号命名的 PNG 和一个 tiles.cfg。2D 手牌与 3D 牌面共用这套原图。 PNG 保留原始比例及透明通道，不拉伸、不二次压缩。可在 tiles.cfg 分别设置 2D、3D 的整包默认位置和缩放，以及每张牌的微调。 牌面代号：万子 11-19、筒子 21-29、索子 31-39、东南西北 41-44、中白发 45-47、春夏秋冬梅兰竹菊 51-58、通用花牌 59；红五万/筒/索为 105/205/305，纯白白板为 2。 其他须知： 1. PNG 单边不超过 4096 像素，牌面单张不超过 4MB，背景和牌背单张不超过 8MB，压缩包及解压后总大小不超过 128MB；缺失牌面使用官方牌面递补。 2. 配置使用 UTF-8，支持 # 整行或行末注释。[2d]、[3d] 设置整包默认值，[2d.11]、[3d.11] 设置单牌相对调整；x/y 是位置百分比（-100～100），scale 是缩放百分比（25～200）。未配置时位置 0、缩放 100；单牌设置叠加在整包设置上。 3. 压缩包内容示例（不需要其他文件）： NewCardFace.zip ├── 11.png ├── 12.png ├── 105.png └── tiles.cfg # tiles.cfg 示例 [2d] x = 0 y = 0 scale = 100 [3d] scale = 100 [2d.11] y = 2 # 一万向上移动 2% [3d.11] scale = 95 也可直接上传 Unity「牌面设计 / 卡牌设计」导出的完整牌包，保留背景、牌背、颜色和全部微调。": "Formato de subida: sube un .zip que contenga directamente los PNG nombrados por código de ficha y un archivo tiles.cfg. Las manos 2D y las caras 3D comparten estas imágenes originales. Los PNG conservan su proporción y transparencia, sin estiramiento ni recompresión. En tiles.cfg puedes definir por separado la posición y escala predeterminadas del paquete para 2D y 3D, además de ajustes por ficha. Códigos: caracteres 11-19, círculos 21-29, bambúes 31-39, Este/Sur/Oeste/Norte 41-44, dragones rojo/blanco/verde 45-47, primavera/verano/otoño/invierno/ciruelo/orquídea/bambú/crisantemo 51-58, flor genérica 59; cincos rojos de caracteres/círculos/bambúes 105/205/305; dragón blanco liso 2. Otros requisitos: 1. Cada lado del PNG no puede superar 4096 píxeles; cada cara, 4MB; cada fondo o reverso, 8MB; el archivo comprimido y el total descomprimido, 128MB. Las caras ausentes se sustituyen por las oficiales. 2. La configuración usa UTF-8 y admite comentarios con # en líneas completas o al final. [2d] y [3d] definen los valores del paquete; [2d.11] y [3d.11], los ajustes relativos de una ficha. x/y indican porcentajes de posición (-100～100) y scale, de escala (25～200). Sin configuración: posición 0, escala 100. Los ajustes por ficha se suman a los del paquete. 3. Ejemplo del contenido (no hacen falta otros archivos): NewCardFace.zip ├── 11.png ├── 12.png ├── 105.png └── tiles.cfg # Ejemplo de tiles.cfg [2d] x = 0 y = 0 scale = 100 [3d] scale = 100 [2d.11] y = 2 # Subir el uno de caracteres un 2% [3d.11] scale = 95 También puedes subir un paquete completo exportado desde «Diseño de caras / Diseño de fichas» de Unity, conservando fondos, reversos, colores y todos los ajustes.",
    "请选择 zip 文件": "Selecciona un archivo zip",
    "已提交，请等待管理员审核": "Enviado. Espera la revisión del administrador.",
    "上传失败": "Error al subir",
    "请先确认资源版权或许可证情况": "Confirma primero los derechos o la licencia del recurso",
    "请确认此牌面背景由你拥有版权，或使用允许非商业使用的许可证。没有版权或许可证的资源只能私下使用，不能上传到平台分享站。": "Confirma que eres titular de los derechos de este fondo de ficha o que su licencia permite el uso no comercial. Los recursos sin derechos o licencia solo pueden usarse en privado; no pueden subirse al sitio de recursos compartidos.",
