    "从宁波早期见证向下核查。日期注明采集、出版或规则版本，不自动等于发明年；“形成时间待证”一行是独立研究队列。点规则名可查来源与待证关系。": "La investigación parte de los primeros testimonios de Ningbo. Las fechas indican recopilación, publicación o versión de reglas; no equivalen automáticamente al año de invención. La fila «Fecha de formación por verificar» es una línea de investigación independiente. Pulsa el nombre de unas reglas para consultar sus fuentes y relaciones pendientes.",
    "按手牌张数、吃牌、计分、百搭等结构特征及具名版本比较；同组不表示同源，历史联系须有原典支持。": "Compara rasgos como tamaño de mano, chow, puntuación y comodines, además de versiones con nombre. Pertenecer al mismo grupo no implica un origen común: las relaciones históricas necesitan fuentes primarias.",
