    "牌谱下载需登录，每人每天 200 局（凌晨 4 点刷新）；分析在本地进行，不限次数": "Inicia sesión para descargar registros: 200 manos por persona al día, renovadas a las 4 de la madrugada. El análisis es local y sin límite de usos.",
    "开发模式下载不限局数。前往牌谱分析页下载并在本地统计。": "En modo de desarrollo no hay límite de descarga. Ve a la página de análisis para descargar registros y calcular estadísticas locales.",
