    "无法打开 2D 牌谱": "No se pudo abrir el registro 2D",
    "无法打开 3D 牌谱": "No se pudo abrir el registro 3D",
    "小林改版国标麻将（2026）：取消 8 番起胡和底分，点和×2，自摸番三。": "Variante MCR de Xiaolin (2026): elimina el mínimo de 8 puntos y los puntos base; victoria por descarte ×2 y puntos triplicados al cerrar del muro.",
    "依据《新编 MCR》推定的本站十六张扩展：十七张和牌、五组一对，八番起和。": "Extensión de dieciséis fichas de esta plataforma, deducida del MCR revisado: victoria con diecisiete fichas, cinco grupos y una pareja; mínimo de ocho puntos.",
    "逐番适用表、五面子复合计番、固定十四张特殊牌形及独听补则。": "Tabla de aplicación por jugada, suma de jugadas con cinco combinaciones, manos especiales fijas de catorce fichas y normas adicionales de espera única.",
    "底本：新编 MCR": "Texto base: MCR revisado",
    "Natsuki 编著，2025年8月版；十六张的扩展约定见上文。": "Compilado por Natsuki, edición de agosto de 2025; las convenciones de dieciséis fichas se explican arriba.",
    "采用《蓝十魔改规则第4版》的四人赛制：136张无花，5分起和、100分封顶，半全铳半分付。PDF中的三人赛制仅供阅读，本平台当前只提供四人房。": "Formato de cuatro jugadores del «Reglamento modificado de Lanshi, 4.ª edición»: 136 fichas sin flores, mínimo de 5 puntos, máximo de 100 y pago a partes iguales entre responsabilidad íntegra y pago compartido. El formato de tres jugadores del PDF es solo de consulta; la plataforma solo ofrece salas de cuatro.",
    "四人规则与番种牌例；线下赛事编排、裁判与纪律条款供参考。": "Reglas para cuatro jugadores y ejemplos de jugadas; organización de torneos presenciales, arbitraje y disciplina como referencia.",
    "国标花混癞子": "MCR con flores comodín",
    "国标四癞子": "MCR con cuatro comodines",
    "新增四张红花癞子，按合法替代的最高国标番计分。": "Añade cuatro flores rojas comodín; se puntúa la sustitución válida con mayor valor MCR.",
    "国标四癞子：本站规则": "MCR con cuatro comodines: reglas de esta plataforma",
    "红花留手、替代限制、八番起和、计分与牌例。": "Flores rojas en la mano, límites de sustitución, mínimo de ocho puntos, puntuación y ejemplos.",
    "标准国标计番与补花流程，每种常规牌三张透明、一张不透明。": "Puntuación y reposición de flores de MCR estándar; tres ejemplares transparentes y uno opaco de cada ficha ordinaria.",
    "透明国标：本站规则与牌例": "MCR transparente: reglas y ejemplos de esta plataforma",
    "三透一暗、吃碰选牌、暗杠、八番起和与普通牌墙。": "Tres transparentes y una opaca, elección de fichas en chow/pung, kong oculto, mínimo de ocho puntos y muro ordinario.",
    "四人三透一暗，透明手牌公开；本站完整规则与外部资料。": "Cuatro jugadores, tres fichas transparentes y una opaca; manos transparentes públicas. Reglas completas de la plataforma y fuentes externas.",
    "鹫巢麻将：本站规则与牌例": "Mahjong Washizu: reglas y ejemplos de esta plataforma",
    "含透明牌、70次摸牌、实时手牌、双打主将制和回放说明。": "Incluye fichas transparentes, 70 robos, manos en tiempo real, parejas con capitán e indicaciones para la repetición.",
    "雀魂2021年明镜之战攻略（日文）": "Guía del evento Espejo de Mahjong Soul de 2021 (japonés)",
    "非官方活动说明，可参考透明牌和选牌方式；与本站的可配置日麻细则并非完全相同。": "Explicación no oficial del evento, útil para las fichas transparentes y su selección; no coincide por completo con las reglas Riichi configurables de esta plataforma.",
    "原作式鹫巢麻将规则（日文）": "Reglas de mahjong Washizu según la obra original (japonés)",
    "用于对照无牌山玩法；其70次弃牌计数与本站70次摸牌不同。": "Referencia para el juego sin muro; su cómputo de 70 descartes difiere de los 70 robos de esta plataforma.",
    "四川麻将包含血战到底，以及血流成河的弃三张、换三张玩法。": "Mahjong Sichuan incluye batalla hasta el final y las modalidades de río de sangre con descarte o intercambio de tres.",
    "血流成河：弃三张与换三张": "Río de sangre: descarte e intercambio de tres",
    "开局选牌、连续和牌、花区展示、当前番表与局终查叫。": "Selección inicial, victorias sucesivas, exposición en la zona de flores, tabla actual de jugadas y comprobación final de espera.",
    "请选择与房间一致的子规则，阅读对应的规则书原文。": "Selecciona la misma variante que la sala y lee su reglamento original.",
    "上海敲麻：上海特色麻将规则，使用144张麻将牌，有着中发白当花、可以垃圾和、听牌后要敲牌报听、番种简单等特点，节奏快且易上手。上海清混碰：上海传统麻将规则，使用144张麻将牌，以必须做出清、混一色或碰碰和才能和牌为特色，与快节奏的上海敲麻有着鲜明对比，独具特色。": "Qiaoma de Shanghái: modalidad local de 144 fichas, con dragones como flores, posibilidad de mano vacía, declaración de espera golpeando las fichas y pocas jugadas; es rápida y fácil de aprender. Qing Hun Peng de Shanghái: modalidad tradicional de 144 fichas que exige Mano pura, Mano semipura o Todo pung para ganar; ofrece una experiencia distintiva frente al ritmo rápido del Qiaoma.",
    "MIL 上海麻将（推广）竞赛规则（试行2024版）": "Reglamento de competición promocional de mahjong Shanghái MIL (edición provisional 2024)",
    "上海敲麻：上海特色麻将规则，使用144张麻将牌，有着中发白当花、可以垃圾和、听牌后要敲牌报听、番种简单等特点，节奏快且易上手。": "Qiaoma de Shanghái: modalidad local de 144 fichas, con dragones como flores, posibilidad de mano vacía, declaración de espera golpeando las fichas y pocas jugadas; es rápida y fácil de aprender.",
    "上海清混碰规则": "Reglas de Qing Hun Peng de Shanghái",
    "上海清混碰：上海传统麻将规则，使用144张麻将牌，以必须做出清、混一色或碰碰和才能和牌为特色，与快节奏的上海敲麻有着鲜明对比，独具特色。": "Qing Hun Peng de Shanghái: modalidad tradicional de 144 fichas que exige Mano pura, Mano semipura o Todo pung para ganar; ofrece una experiencia distintiva frente al ritmo rápido del Qiaoma.",
    "上海垃圾和规则（2026-10-17 修订）": "Reglas de Lajihu de Shanghái (revisión 2026-10-17)",
    "上海垃圾和是上海本地的一款特色麻将规则，使用144张麻将牌，允许垃圾和的同时对点和做了花数上的限制，并有七对子、自摸加底等特色内容，节奏适中。": "Lajihu de Shanghái es una modalidad local de 144 fichas y ritmo moderado. Permite manos vacías, pero exige cierto número de flores para ganar por descarte; incluye Siete parejas y aumento de la base al cerrar del muro.",
    "马来三麻": "Mahjong malasio de tres jugadores",
    "传统84张：筒、字、16花与4飞，东南西三席，5番起和；依据 Cheah / Sloper 定型文及平台补充条款。": "84 fichas tradicionales: círculos, honores, 16 flores y 4 fei; asientos Este, Sur y Oeste; mínimo de 5 fan. Sigue el texto de referencia de Cheah / Sloper y las normas adicionales de la plataforma.",
    "马来西亚三人麻将平台规则书": "Reglamento de la plataforma para mahjong malasio de tres jugadores",
